(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c21"]=[{"id":"00000182","register_sub_id":"101","register_pk":"101172","name":"平源旅館土蔵","kana":"ひらげんりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市大町6-24","lat":39.31522449,"lng":140.56859758,"geo_status":"db","era":"大正15以前","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建，鋼板葺，建築面積81㎡","structure_material":"土蔵造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"05 － 0014","desc":"本館の脇に、同じく街道に面して建つ土蔵である。大正15年の火災に際して本館は焼失したが、この土蔵は難を逃れた。腰の部分を石張とする外観が特徴的であり、洋風の本館部分と好対照をなす。大火以前の横手の様子を今日に伝える建物として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000182"},{"id":"00000181","register_sub_id":"101","register_pk":"101171","name":"平源旅館本店","kana":"ひらげんりょかんほんてん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市大町6-24","lat":39.31540133,"lng":140.56868259,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建，鋼板葺，建築面積675㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"05 － 0013","desc":"旧街道に面して建つ旅館で、皇族が宿泊するなど高い格式を誇る。外観は洋風であるが、内装のほとんどは和風である。意匠ではなく部材の取り扱いで格を示す内装や、玄関部やトイレなどのタイルの意匠、ファサード廻りの装飾などが特に優れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000181"},{"id":"00005536","register_sub_id":"101","register_pk":"106524","name":"森九商店主屋","kana":"もりきゅうしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県秋田市新屋表町9-40","lat":39.68086557,"lng":140.08266927,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、鋼板葺、建築面積175㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"05 － 0143","desc":"醸造業の多い表町の旧街道沿いに西面して建つ。桁行１１間半，梁間５間の規模で，木造平屋建，切妻造，鋼板葺，妻入とし，南側を通り土間とする。正面は奥行１間半の下屋庇を出し，その上方の妻面には梁組を表して意匠とし，旧街道の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005536"},{"id":"00004496","register_sub_id":"101","register_pk":"105486","name":"森長旅館土蔵","kana":"もりちょうりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県男鹿市船川港船川字栄町82","lat":39.88390466,"lng":139.84733203,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、鉄板葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"05 － 0115","desc":"本館から庭を挟んだ敷地北東隅に建つ。土蔵造２階建で，切妻造の置屋根を鉄棒の方杖が支える。西面に戸口を設け，両妻に各１箇所の窓を開く。男鹿石の切石基礎上に建ち，外壁は白漆喰塗で，腰部と鉢巻を黒漆喰塗とする。街路側の窓周りの漆喰彫刻が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004496"},{"id":"00004495","register_sub_id":"101","register_pk":"105485","name":"森長旅館離れ","kana":"もりちょうりょかんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"秋田県","address":"秋田県男鹿市船川港船川字栄町82","lat":39.88378745,"lng":139.84725273,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積79㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"05 － 0114","desc":"本館の東南に位置し，附属棟から２階の渡廊下で接続する木造２階建である。屋根は寄棟造で鉄板葺とする。外壁は下見板張である。１階は物置で２階に１０畳と８畳の床構えをもつ客室を設ける。北面に庇を付けて１間幅の廊下とし，手摺付の濡縁を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004495"},{"id":"00004494","register_sub_id":"101","register_pk":"105484","name":"森長旅館本館","kana":"もりちょうりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県男鹿市船川港船川字栄町82","lat":39.88388169,"lng":139.84712683,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積237㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"05 － 0113","desc":"角地に建つ木造２階建洋風旅館で，方形マンサード屋根を鉄板葺とする。外壁はモルタル仕上で隅柱を見せ，胴蛇腹と軒蛇腹を廻す。北面玄関は起り破風に蝙蝠を飾る。内部は中廊下で和室の客室を配し，背面には厨房等を置く。船川港の往時の賑わいを伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004494"},{"id":"00008241","register_sub_id":"101","register_pk":"133883","name":"山中吉助商店座敷蔵","kana":"やまなかきちすけしょうてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町104","lat":39.20353881,"lng":140.54652803,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積131㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0177","desc":"細長い敷地の中央に位置する、妻入の２階建土蔵。西妻や開口部を黒漆喰、他を白漆喰とする。１階は当初は前後二室に分け、後方の室には棹を漆塗とする棹縁天井を張る。１階は一尺五寸毎に栗と杉の柱を交互に密に建てる。当地域の典型的な意匠を示す座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008241"},{"id":"00000810","register_sub_id":"101","register_pk":"101800","name":"料亭金勇","kana":"りょうていかねゆう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県能代市柳町13-8","lat":40.20896537,"lng":140.02537986,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積469㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"05 － 0034","desc":"県内屈指の老舗料亭の大規模和風建築。外観は，２階に手摺り，１階に庇を付け正面及び側面両端に入母屋屋根を付ける賑やかな構成になる。１１０畳大の２階大広間はじめ各室は上質な造りになり，秋田杉の本場能代を象徴する建物として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000810"},{"id":"00001479","register_sub_id":"101","register_pk":"102469","name":"阿久津家住宅店蔵","kana":"あくつけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県南会津郡南会津町針生字鳥井戸1186","lat":37.18841374,"lng":139.66029581,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積127㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"07 － 0036","desc":"北を正面として建ち，墨書より大正５年の建築とわかる。寄棟造・妻入で，平面は凸形になる。北突出部が土蔵造・２階建で座敷をもち，南が真壁造・平屋建で広間と土間を配し，鉄板葺（もと茅葺）の大屋根を架けた形式で，この地方では店蔵造といわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001479"},{"id":"00001163","register_sub_id":"101","register_pk":"102153","name":"和泉屋旅館主屋","kana":"いずみやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南会津郡南会津町田島字上町甲4047、4048","lat":37.20090258,"lng":139.77255927,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造２階建，瓦葺，建築面積536㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"07 － 0030","desc":"田島町の市街のほぼ中央に建つ木造２階建の旅館建築。昭和９年５月の大火直後に再建された。棟梁は越後の大工で、要所に銘木を用いており全体に凝った造りとなる。正面中央に組物付きの向唐破風造りの大玄関が付く特異な外観は、広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001163"},{"id":"00001164","register_sub_id":"101","register_pk":"102154","name":"和泉屋旅館土蔵","kana":"いずみやりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南会津郡南会津町田島字上町甲4047","lat":37.20109651,"lng":139.77259007,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，鉄板葺，建築面積115㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"07 － 0031","desc":"奥行きの長い敷地の中央東端に建つ妻入の南北棟で、建築年代は様式から明治期と推定される。間口２間半、奥行６間で、南面に庇が付く。内外の造作とも標準的な規模になり、営業用の什器類を納める。屋根は置屋根とし、上部に昭和９年の大火の痕跡が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001164"},{"id":"00001856","register_sub_id":"101","register_pk":"102846","name":"御菓子師玉嶋屋主屋","kana":"おんかししたましまやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県二本松市本町一丁目86","lat":37.5914,"lng":140.43605,"geo_status":"db","era":"大正8頃／昭和13増築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、金属板葺、建築面積251㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"07 － 0042","desc":"旧国道４号線に面して建つ。大正７年の大火後の再建になり，木造２階建，銅板瓦棒葺，切妻造，平入の店舗の奥に応接室，台所，昭和１３年建設の座敷を通土間に沿って配する。正面庇上に立てた２本の袖看板が特徴的で，屋号を打ち出した銅細工にも見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001856"},{"id":"00000510","register_sub_id":"101","register_pk":"101500","name":"花水館奥の間（御殿）","kana":"かすいかんおくのま（ごてん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字西滝ノ町21","lat":37.83459505,"lng":140.45238351,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積71㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0008","desc":"貴賓客が宿泊するための座敷で，旅館の中庭に建つ。１０畳間２室からなる室内は，柱や天井等の造作に良質な材料を用い，床の間等に銘木を用いる等，入念で優れた仕上げになる。平屋建ながら２重の銅板屋根を持つ外観はこの時代の特徴を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000510"},{"id":"00008812","register_sub_id":"101","register_pk":"162255","name":"冠木商店質蔵","kana":"かぶきしょうてんしちぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県喜多方市字一丁目4536-1","lat":37.65337698,"lng":139.87293403,"geo_status":"db","era":"天保13年(1842)","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0126","desc":"座敷蔵の東に位置する。東西棟の切妻造桟瓦葺、桁行11ｍ梁間4.8ｍで、西面に蔵前を設ける。土蔵造2階建。漆喰仕上げとし、西面には両開戸の出入口、東面には片開戸の窓2箇所を穿ち、いずれも掛子塗。市内に残る古い土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008812"},{"id":"00008811","register_sub_id":"101","register_pk":"162254","name":"冠木商店主屋及び座敷蔵","kana":"かぶきしょうてんしゅおくおよびざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県喜多方市字一丁目4536-1","lat":37.65336847,"lng":139.87267706,"geo_status":"db","era":"嘉永7年(1854)／明治中期増築・昭和4年改築","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造及び土蔵造2階建、瓦葺、建築面積268㎡","structure_material":"木造及び土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0125","desc":"通りに西面する敷地の西寄りに主屋を建て、東に座敷蔵、南に2階座敷を付設。建築面積268㎡の木造及び土蔵造2階建、入母屋棟と切妻棟を組み合わせる桟瓦葺屋根。座敷蔵は漆喰仕上げで、一部を黒漆喰とする。良質な座敷を残す、老舗商家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008811"},{"id":"00008813","register_sub_id":"101","register_pk":"162256","name":"冠木商店南の蔵","kana":"かぶきしょうてんみなみのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4536-1","lat":37.65331061,"lng":139.87292211,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0127","desc":"質蔵の南に位置し、南は小路沿いとなる。東西棟の切妻造桟瓦葺、桁行11ｍ梁間4.8mで、蔵前を設ける。蔵前は瓦葺庇をかけ、軒まで塗り込める。小路側は腰に煉瓦を積み、上部を中塗、鉢巻を漆喰仕上げとし、街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008813"},{"id":"00002351","register_sub_id":"101","register_pk":"103341","name":"旧甲斐家住宅店蔵","kana":"きゅうかいけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字1-4611","lat":37.65644047,"lng":139.87212035,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積103㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"07 － 0056","desc":"江戸期には酒造業，明治以後味噌醤油の醸造業を営む商家の店蔵。一階に店舗，応接間，２階に座敷を配し，上下階を螺旋状の階段で連絡する。立ちが高く，２階の軒を大きく持ち出した重厚な外観を造るとともに，２階窓回りなど細部には精巧な仕事がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002351"},{"id":"00012872","register_sub_id":"101","register_pk":"367980","name":"旧採進堂酒店主屋","kana":"きゅうさいしんどうさけてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字湯沢9-2","lat":37.832225,"lng":140.45259167,"geo_status":"db","era":"明治31年頃／昭和10年頃・同50年代増築、昭和30年代改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"07 － 0210","desc":"飯坂温泉中心部の街路に北面して建つ。切妻造桟瓦葺の二階建一部平屋建、背面東側にカッテ、ザシキを突出し、二階の中廊下沿いに居室を配する。二階正面は出格子と当地域特有の鎬付の出梁を備え、下屋上に銘酒の看板を並べる。近代温泉地の隆盛を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012872"},{"id":"00008816","register_sub_id":"101","register_pk":"162259","name":"旧嶋新商店一号蔵・二号蔵及び三号蔵","kana":"きゅうしましんしょうてんいちごうくら・にごうくらおよびさんごうくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4647-1","lat":37.65357634,"lng":139.87169238,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積204㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0130","desc":"東西に長い敷地中央に位置する。桁行36ｍに及ぶ2階建土蔵。東から3室に分け、東端の1号蔵は東面に蔵前を設け、2・3号蔵は南面に出入口を穿つ。切妻造桟瓦葺。腰板張の漆喰仕上げで、鳥居型に仕上げた窓を要所に配し、リズミカルな外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008816"},{"id":"00008815","register_sub_id":"101","register_pk":"162258","name":"旧嶋新商店座敷蔵及び主屋","kana":"きゅうしましんしょうてんざしきぐらおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4647-1","lat":37.65348807,"lng":139.87206224,"geo_status":"db","era":"明治11年／明治中期・昭和後期改修","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"土蔵造及び木造2階建、瓦葺及び鉄板葺、建築面積185㎡","structure_material":"土蔵造及び木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0129","desc":"店舗蔵西に座敷蔵、主屋と続く。座敷蔵は東西棟の切妻造桟瓦葺で、南面に下屋を付設。土蔵造2階建、漆喰仕上げ、2階に掛子塗戸を吊る。南面に廊下を通し、トコを構えるザシキなど3室を北側に並べ、西奥に主屋の板間や台所を配する。喜多方の町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008815"},{"id":"00008814","register_sub_id":"101","register_pk":"162257","name":"旧嶋新商店店舗蔵","kana":"きゅうしましんしょうてんてんぽぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4647-1","lat":37.65342923,"lng":139.87222932,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0128","desc":"通りに東面する平入町家。切妻造桟瓦葺の木造2階建で、正・背面に下屋を付設。間口12ｍ奥行9.0ｍ。1階は店舗、2階に座敷3室を配する。正面2階は漆喰塗大壁造とし、窓を3所穿つ。妻壁は煉瓦積。煉瓦と漆喰壁が印象的な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008814"},{"id":"00008817","register_sub_id":"101","register_pk":"162260","name":"旧嶋新商店四号蔵","kana":"きゅうしましんしょうてんよんごうくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4647-1","lat":37.65363938,"lng":139.87142128,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0131","desc":"3号蔵西に東西棟で建つ。東面切妻造、西面寄棟造の桟瓦葺、桁行9.6ｍ梁間5.7ｍの土蔵造2階建。南面東に庇を付け、掛子塗戸を吊る。腰板張、漆喰仕上げ、窓枠は鳥居型で鉄扉を開く。大規模な2階建土蔵が連続する重厚な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008817"},{"id":"00008818","register_sub_id":"101","register_pk":"162261","name":"旧山時呉服店家財蔵","kana":"きゅうやまときごふくてんかざいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県喜多方市字一丁目4647-2","lat":37.65385668,"lng":139.87163127,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0132","desc":"通りの西側に占める短冊形の敷地中央に位置する。桁行13ｍ梁間6.7ｍの2階建土蔵。切妻造桟瓦葺、南面の中央に出入口を穿ち、引戸をたてる。出入口まわりや南面の腰をモルタル仕上げ、小屋組をトラス組とするなど近代的な仕様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008818"},{"id":"00014731","register_sub_id":"101","register_pk":"518989","name":"栗花家住宅主屋","kana":"くりはなけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県伊達郡桑折町字北町76","lat":37.847625,"lng":140.51868889,"geo_status":"db","era":"明治41年／昭和後期増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"07 - 0282","desc":"旧蚕物商の店蔵の東に接続して建つ主屋。平屋建切妻造桟瓦葺の東西棟で、敷地北辺に寄せて建ち、南側に通路を設ける。内部は四室を配して北東隅を床構え付き座敷とし、東に風呂便所を角屋で延ばす。店蔵と一体となって街道沿いの歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014731"},{"id":"00014730","register_sub_id":"101","register_pk":"518988","name":"栗花家住宅店蔵","kana":"くりはなけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県伊達郡桑折町字北町76","lat":37.84763056,"lng":140.518575,"geo_status":"db","era":"明治41年／平成23年改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"07 - 0281","desc":"桑折宿の中心部に位置する蚕物商の店蔵。奥州街道に西面する二階建切妻造平入鉄板葺で、外壁は軒まで塗込め、二階南北妻に窓を各1箇所開ける。一階は前土間のミセで摺上戸を残し、二階は一室で繭の保管場。重厚な外観が街道沿いの歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014730"},{"id":"00011631","register_sub_id":"101","register_pk":"210647","name":"源泉亭湯口屋旅館本館","kana":"げんせんていゆぐちやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県岩瀬郡天栄村大字湯本字居平14-1他","lat":37.278758,"lng":139.991437,"geo_status":"db","era":"明治4年頃","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造2階建、茅葺、建築面積405㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"07-0175","desc":"集落の中央通り最奥に建つ旅館。木造二階建、寄棟造茅葺屋根。傾斜地に建つため各階床高に段差が設けられている。一階茶の間は吹抜けとして上部梁を表し、二階には客室を配す。大規模な茅葺建物で、湯治場として知られる岩瀬湯本温泉の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011631"},{"id":"00008247","register_sub_id":"101","register_pk":"133889","name":"島慶園店舗蔵","kana":"しまけいえんてんぽぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県喜多方市字二丁目4656-3","lat":37.65269099,"lng":139.87227407,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0109","desc":"通りに西面して建つ。間口１０ｍの土蔵造２階建、切妻造桟瓦葺で、正面に下屋を付設する。白漆喰仕上げで、２階窓まわりを黒漆喰とする。１階を広い店舗、２階を板敷の倉庫とし、トラス組を現す。店蔵が建ち並ぶ通りに位置し、伝統的な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008247"},{"id":"00013495","register_sub_id":"101","register_pk":"504860","name":"鈴木屋利兵衛旧主屋","kana":"すずきやりへえきゅうおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県会津若松市大町一丁目357","lat":37.498725,"lng":139.92837778,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0241","desc":"店蔵の背後に接続して建つ。木造平屋建、切妻造鉄板葺で、外壁は漆喰で軒先まで塗込める。内部は一列四室を配して北東に土間を突出する。小屋組を土で塗込める他、居室部の柱や長押なども塗込めた上で化粧板を張るなど、当主の高い防火意識の反映を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013495"},{"id":"00013494","register_sub_id":"101","register_pk":"504859","name":"鈴木屋利兵衛店蔵","kana":"すずきやりへえみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県会津若松市大町一丁目357","lat":37.49859167,"lng":139.92833889,"geo_status":"db","era":"江戸末期／明治43年頃・昭和46年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積125㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0240","desc":"旧若松城下の北方郭外にある代々塗物を扱う商家。街道に南面して建つ土蔵造の店蔵は、正面、西面に下屋を廻し、外壁を黒漆喰で出桁造の軒先まで塗込める。内部二階は、明治末期に天井や階段手摺などを洋風に設えた。重厚な店蔵への洋風意匠導入の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013494"},{"id":"00013496","register_sub_id":"101","register_pk":"504591","name":"関善吉薬局店蔵","kana":"せきぜんきちやっきょくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市川原町161","lat":37.490075,"lng":139.91510556,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0242","desc":"若松城下の西方郭外にある薬局。旧下野街道に北面して建つ土蔵造二階建で、正面に下屋を付す。外壁は黒漆喰で出桁造の軒先まで塗込める。内部一階には調剤室、薬品棚を設けるほか、下屋境に防火対策で漆喰塗の大型引戸を備えるなど、当時の商家の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013496"},{"id":"00013028","register_sub_id":"101","register_pk":null,"name":"竹藤主屋","kana":"たけとうおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市中央一丁目69","lat":37.49821667,"lng":139.92990833,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、金属板葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0221","desc":"店舗の北背面に接続する。南から客間、中間、勝手の３室を並べ東に廊下を通す当地方の典型的な平面である。廊下の東は中庭とする。柱と長押に丸太の面皮材、落し掛に竹を用い、床脇物入は敷居下になぐりの蹴込板を入れるなど、数寄屋風の意匠で整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013028"},{"id":"00013030","register_sub_id":"101","register_pk":null,"name":"竹藤座敷蔵","kana":"たけとうざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県会津若松市中央一丁目69","lat":37.49838889,"lng":139.93003333,"geo_status":"db","era":"文政6年（1823）／昭和58年・同60年頃改修","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0223","desc":"敷地の北東に建つ南北棟で、外壁は漆喰塗とする。南妻の戸口は漆喰塗扉の両開きである。内部１階は南から前室、次の間、座敷が並ぶ。２階は家財蔵とする。座敷・次の間境中央に２階梁受け柱が立ち、低い根太天井、奥行の浅い床棚など、古風な座敷蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013030"},{"id":"00013029","register_sub_id":"101","register_pk":null,"name":"竹藤竹蔵","kana":"たけとうたけぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県会津若松市中央一丁目69","lat":37.4984,"lng":139.92997222,"geo_status":"db","era":"天明5年(1785)／文久2年(1862)移築、昭和60年頃改修","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0222","desc":"敷地の北西に建つ桁行７間の南北棟で、外壁は蔵前下屋廻りとも塗込とし、南妻上部に井桁の屋号を塗出す。２階窓は鉄扉両開きとする。内部は土間床で商品蔵兼加工場であった。小屋組は１間毎に登り梁を架け、裏板を漆喰揚塗とする。重厚な構造の土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013029"},{"id":"00013027","register_sub_id":"101","register_pk":"368337","name":"竹藤店舗","kana":"たけとうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県会津若松市中央一丁目69","lat":37.49814444,"lng":139.92989167,"geo_status":"db","era":"天保12年（1841）／昭和45年改修","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造2階建、金属板葺、建築面積82㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0220","desc":"街路に南面して建つ間口７間の大型店舗で、正面に下屋を付す。内部は東半が土間みせ、西半が床上の帳場で西端を倉庫とし、２階は物置とする。一階下屋正面は一間幅の腰高障子を立て、下屋境は全面摺上戸、二階正面は板壁とする。古い店舗形式を残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013027"},{"id":"00000512","register_sub_id":"101","register_pk":"101502","name":"なかむらや旅館新館","kana":"なかむらやりょかんしんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字湯沢18","lat":37.83226146,"lng":140.45233483,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造３階建一部平屋建，瓦葺，建築面積78㎡","structure_material":"土蔵造３階建一部平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0010","desc":"現所有者の祖先が営業を始め間もない頃の建築と伝える。本館と同じ土蔵造，木造３階建だが，全階平面が同大で２・３階が高く開放的な点は好対照をなす。本館とともに特異な外観で，人々の目を引く建物である。西側には旧土蔵(本館と同じ頃)が附属する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000512"},{"id":"00000511","register_sub_id":"101","register_pk":"101501","name":"なかむらや旅館本館","kana":"なかむらやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県福島市飯坂町字湯沢18","lat":37.83214902,"lng":140.45232806,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造３階建，瓦葺，建築面積209㎡","structure_material":"土蔵造３階建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0009","desc":"江戸時代に創業した旅館を現所有者の祖先が買い取り営業を続けたと伝える。創業時の施設と伝える本館は，外壁を土蔵造とする。外観には後世の改造がみられるが，３階を１・２階より小さくして安定感をもたせた重厚な姿は特異で，町中で特に目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000511"},{"id":"00011854","register_sub_id":"101","register_pk":"211042","name":"ぬる湯温泉旅館・二階堂帳場棟","kana":"ぬるゆおんせんりょかん・にかいどうちょうばとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市桜本字温湯11","lat":37.728935,"lng":140.293293,"geo_status":"db","era":"明治15年頃／大正12年増築、昭和50年・平成5年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積120㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"07-178","desc":"中座敷棟の東に東西棟で接続する。一階は正面側に全長に渡る土間を配し、床上部は居室にあてる。二階は大正一二年の増築で、客室四室を並べ北に廊下、南に広縁を付ける。客室は床の間を備え、東西各二室は部屋境は襖で一室ともなり、欄間を入れ意匠に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011854"},{"id":"00011853","register_sub_id":"101","register_pk":"211041","name":"ぬる湯温泉旅館・二階堂中座敷棟","kana":"ぬるゆおんせんりょかん・にかいどうなかざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市桜本字温湯11","lat":37.729012,"lng":140.293029,"geo_status":"db","era":"明治35年頃／平成5年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積234㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"07-177","desc":"古家棟の東北に東西棟で接続する。一、二階とも二列各五室の客室を並べ、四周に廊下を廻らす。二階は床の間・床脇を備え、長押を廻した上質な造りである。外壁は下見板張で、モールディング付額縁の窓と雲形の持送りなど、和洋折衷の意匠を特徴とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011853"},{"id":"00011852","register_sub_id":"101","register_pk":"211040","name":"ぬる湯温泉旅館・二階堂古家棟","kana":"ぬるゆおんせんりょかん・にかいどうふるやとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市桜本字温湯11","lat":37.728986,"lng":140.292829,"geo_status":"db","era":"明治5年頃／昭和32年増築、平成18年改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造3階建、茅葺、建築面積166㎡","structure_material":"木造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"07-176","desc":"福島市西部にある温泉施設。一、二階は廊下を十字に配し、四方に二室ずつ広縁付の客室を設ける。茅葺屋根は、西側を寄棟造とするが、東側を半切妻造のあづま造として当地方特有の外観を見せ、妻面の垂木を扇状に配し凝った意匠とし、景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011852"},{"id":"00014999","register_sub_id":"101","register_pk":"529277","name":"藤田家住宅座敷蔵","kana":"ふじたけじゅうたくざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県白河市二番町46-1","lat":37.12558056,"lng":140.20435278,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"07 - 0285","desc":"店舗兼主屋の北西に建つ座敷蔵。二階建切妻造銅板葺で外壁漆喰塗仕上。軒に鉢巻を廻らす。１階は２室を配し西室南に蔵前が付く。東室は床と床脇を構え東辺に縁を付す。床廻りは黒檀や紫檀など用材吟味し、湾曲状の削出材でつなぐ違棚など良質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014999"},{"id":"00014998","register_sub_id":"101","register_pk":"529276","name":"藤田家住宅店舗兼主屋","kana":"ふじたけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県白河市二番町46-1","lat":37.12540833,"lng":140.20433333,"geo_status":"db","era":"大正前期／昭和中期・平成30年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階一部平屋建、瓦葺一部銅板葺、建築面積169㎡","structure_material":"木造2階一部平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"07 - 0284","desc":"小峰旧城下の角地に建つ味噌醤油醸造業の店舗兼主屋。奥州街道に東面する2階建切妻造平入桟瓦葺の店舗の西に平屋建銅板葺の主屋を接続。店舗一階は広い土間、二階は三室を矩折れに並べ、南西が床構え付き座敷。ガラス戸の開放的な外観が街道景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014998"},{"id":"00015000","register_sub_id":"101","register_pk":"529278","name":"藤田家住宅土蔵","kana":"ふじたけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県白河市二番町46-1","lat":37.12560833,"lng":140.204225,"geo_status":"db","era":"江戸末期／明治41年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"07 - 0286","desc":"座敷蔵の西に位置する家財蔵。切石積基礎に建つ二階建切妻造銅板葺で、外壁は漆喰塗仕上、軒に鉢巻を廻らす。東妻を戸口とし、各階板敷の一室で北西に階段を配す。小屋組は中古で、登梁を水平の繋梁で挟む。西妻に庇付窓を上下に開け、敷地北西景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015000"},{"id":"00011045","register_sub_id":"101","register_pk":"205152","name":"松本屋家財蔵","kana":"まつもとやかざいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字三丁目4791","lat":37.650269,"lng":139.871942,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0164","desc":"敷地南東隅に建つ家財蔵。土蔵造二階建、切妻造桟瓦葺平入で、北面に出入口を開く。内部は一階をコンクリート土間とする。外壁は腰をモルタル塗とする他は漆喰塗で、北面に開く窓三所には片開鉄扉を付すなど、文庫蔵とほぼ共通の意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011045"},{"id":"00011043","register_sub_id":"101","register_pk":"205150","name":"松本屋店舗蔵","kana":"まつもとやてんぽぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県喜多方市字三丁目4791","lat":37.650409,"lng":139.871501,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0162","desc":"短冊状敷地の、街路に西面して建つ土蔵造二階建の店蔵。一階は店舗で正面に三尺の下屋を付す。二階は八畳二室の座敷を並べる。外壁は腰人造石吹付仕上、他は漆喰塗とし、二階正面には両開き土戸付の窓を三連並べ、袖壁付小庇を付すなど、重厚な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011043"},{"id":"00011044","register_sub_id":"101","register_pk":"205151","name":"松本屋文庫蔵","kana":"まつもとやぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字三丁目4791","lat":37.650299,"lng":139.871828,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0163","desc":"敷地南側のやや東寄りに建つ文庫蔵。土蔵造二階建、切妻造桟瓦葺妻入で、西面正面に前室を付す。内部は一階二階とも板床で要所に物入を付す。外壁は腰をモルタル塗とする他は漆喰塗で、窓には片開鉄扉が付くが、正面二階窓は両開き土戸として正面性を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011044"},{"id":"00000024","register_sub_id":"101","register_pk":"101014","name":"向瀧客室棟（会議室、菊の間他）","kana":"むかいたききゃくしつとう（かいぎしつ、きくのまほか）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市東山町大字湯本字川向200","lat":37.4780661,"lng":139.96051797,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造3階建、瓦葺、建築面積360㎡","structure_material":"木造3階建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0004","desc":"向瀧客室棟（会議室，菊の間他）は，客室棟（花月の間，梅の間他）とともに東京の棟梁の手になり，地元の職人が多くの造作を手がけたと伝える。数寄屋風の客間や洋風の会議室等の各室の意匠に特徴があり，当時の職人技術の水準を示した建物の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000024"},{"id":"00000023","register_sub_id":"101","register_pk":"101013","name":"向瀧客室棟（花月の間、梅の間他）","kana":"むかいたききゃくしつとう（かげつのま、うめのまほか）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市東山町大字湯本字川向200","lat":37.47819094,"lng":139.96064167,"geo_status":"db","era":"明治30代","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0003","desc":"向瀧客室棟（花月の間，梅の間他）は，東京から棟梁を呼んでつくったと伝える建物で，書院造風の意匠をもつ客室には，地元の職人矢仲喜代八が作った建具が残る。当時の東京と会津の職人の技術水準の高さを示した建物の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000023"},{"id":"00000021","register_sub_id":"101","register_pk":"101011","name":"向瀧玄関","kana":"むかいたきげんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市東山町大字湯本字川向200","lat":37.47807412,"lng":139.9610895,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建、瓦葺、建築面積636㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0001","desc":"向瀧は江戸時代に「きつね湯」の愛称で親しまれた温泉保養所で，明治６年から旅館となった。玄関は，浴場「きつね湯」がある建物で，道路に面した大きな入母屋造の屋根や２階の大広間に特徴があり，会津東山温泉の歴史的景観を知る上で欠くことができない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000021"},{"id":"00000022","register_sub_id":"101","register_pk":"101012","name":"向瀧はなれ","kana":"むかいたきはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市東山町大字湯本字川向200","lat":37.47789659,"lng":139.96087074,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0002","desc":"向瀧はなれは，玄関と同時に建設されたもので，工事は会津若松の棟梁本間辰五郎が手がけた。トコ・違棚を備えた本格的な書院造風の意匠になる続き間座敷をもった建物で，向瀧に残る各建物の規範となった建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000022"},{"id":"00009426","register_sub_id":"101","register_pk":"194219","name":"矢部家住宅一号蔵","kana":"やべけじゅうたくいちごうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字西町2840","lat":37.65306061,"lng":139.88025495,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0134","desc":"座敷蔵の北側に南北棟で建つ。土蔵造二階建、桁行九・六メートル梁間四・七メートル、切妻造桟瓦葺で、東面の戸口に下屋を設ける。外壁は漆喰塗で腰を簓子下見板張とし、南妻面は上下に二箇所ずつ窓を穿つ。座敷蔵や綿蔵とともに商家の屋敷構えを特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009426"},{"id":"00009425","register_sub_id":"101","register_pk":"194218","name":"矢部家住宅座敷蔵","kana":"やべけじゅうたくざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字西町2840-2","lat":37.65290357,"lng":139.88035013,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0133","desc":"敷地中央に南北棟で建つ。土蔵造二階建、切妻造桟瓦葺で、南面を下屋とする。外観は漆喰塗で軒の繰蛇腹を深めて重厚な構えとする。内部は下階に座敷二室を並べてトコなどを整え、南端を広縁とし、上階は家財蔵に用いる。主に接客用に使用する、上質な座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009425"},{"id":"00009427","register_sub_id":"101","register_pk":"194220","name":"矢部家住宅綿蔵","kana":"やべけじゅうたくわたぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字西町2840","lat":37.65315579,"lng":139.88025495,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0135","desc":"敷地北端に東西棟で建つ。土蔵造二階建、桁行四・三メートル梁間五・二メートル、切妻造桟瓦葺で、東妻面の戸口に下屋を設ける。外壁は漆喰塗で軒蛇腹を廻らし、腰を洗出しとする。通り沿いの北面二階の窓には掛子塗の扉を両開きに吊り、街路景観を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009427"},{"id":"00002353","register_sub_id":"101","register_pk":"103343","name":"若喜商店店舗","kana":"わかきしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県喜多方市字3-4786","lat":37.65010757,"lng":139.87142139,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、建築面積98㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"07 － 0058","desc":"味噌醤油醸造業を営む商家の店舗。木造２階建で，地元出身の本間嘉平の設計による。外観は，屋根をコンクリートスラブ陸屋根，外壁をタイル張りとしたモダニズムの意匠でまとめられ，八角の小窓や張出し窓を設け変化を付ける。角地に建ち町並みに異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002353"},{"id":"00002504","register_sub_id":"101","register_pk":"103494","name":"市島銃砲火薬店店舗","kana":"いちじまじゅうほうかやくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市七日町5-10-53","lat":38.25084783,"lng":140.34172093,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、亜鉛メッキ銅板葺、建築面積45㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0040","desc":"江戸時代より火薬を扱っていた商家で通りに面して建ち，１階が店舗，２階は畳敷の和室になる。外壁はモルタル洗出し仕上げで，目地や柱型及び柱頭飾をつくり，石造風の意匠とする。山形で最初の鉄筋コンクリート造店舗建築で，小規模ながら重厚な造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002504"},{"id":"00012469","register_sub_id":"101","register_pk":"367764","name":"旧小池薬局恵比寿屋本店","kana":"きゅうこいけやっきょくえびすやほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県鶴岡市本町一丁目6-88","lat":38.72718,"lng":139.83075,"geo_status":"geocoded","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積136㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"06 － 0191","desc":"市中心部の銀座通りに建つ事務所ビル。長方形平面の鉄筋コンクリート造三階建で、正面一階を石造風、二階以上をタイル張とし、コーニス中央にメダイヨンを飾る。内部は一階を店舗、二階以上を事務室とする。県内における初期鉄筋コンクリート造ビルの好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012469"},{"id":"00010554","register_sub_id":"101","register_pk":"201128","name":"旧丸中横仲商店江戸蔵","kana":"きゅうまるなかよこなかしょうてんえどぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県長井市あら町2461他","lat":38.10101534,"lng":140.03859852,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"06－0158","desc":"敷地北寄り、質蔵の北、粉蔵の東に位置する。桁行九・五メートル梁間四・八メートル、土蔵造二階建、妻入である。小屋はアーチ状の梁で棟木を受け、垂木を架ける。外壁漆喰塗で東面に質蔵同様の縦長窓を設け、掛子塗の土戸を吊るなど、高い左官技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010554"},{"id":"00010553","register_sub_id":"101","register_pk":"201127","name":"旧丸中横仲商店粉蔵","kana":"きゅうまるなかよこなかしょうてんこなぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県長井市あら町2461他","lat":38.10102353,"lng":140.03844335,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、鉄板葺、建築面積55㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"06－0157","desc":"敷地北辺中央の西寄りに、東西棟で江戸蔵と並び建つ。桁行九・五メートル梁間五・七メートル、木造平屋建で、東妻を戸口とし、両妻上部にガラリを付ける。小屋は和小屋で隅部に火打梁を架ける。西面窓の庇を受ける鉄製持送りの幾何模様意匠が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010553"},{"id":"00010550","register_sub_id":"101","register_pk":"201124","name":"旧丸中横仲商店砂糖蔵","kana":"きゅうまるなかよこなかしょうてんさとうぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市あら町2459-2他","lat":38.100836,"lng":140.03852,"geo_status":"db","era":"明治7年","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造、鉄板葺、建築面積47㎡","structure_material":"土蔵造","registered":"2015.08.04(平成27.08.04)","register_no":"06－0154","desc":"最上川の舟運で栄えた長井市街地に建つ土蔵群の一つ。東西に長い敷地の、中央南寄りに位置する。東西棟の土蔵造平屋建で、置屋根形式とする。かつて商品の砂糖を納めた蔵で、桁行約一二メートルを測る大型の蔵。妻側には上下二段に掛子塗の開口部を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010550"},{"id":"00010552","register_sub_id":"101","register_pk":"201126","name":"旧丸中横仲商店質蔵","kana":"きゅうまるなかよこなかしょうてんしちぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市あら町2460他","lat":38.10091775,"lng":140.03858952,"geo_status":"db","era":"明治8年","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"06－0156","desc":"敷地の中央東寄り、土蔵の東隣に東西棟で建つ。土蔵造二階建、平入で、屋根は置屋根形式とする。東面に並べて設けた縦長窓は、上下階で縦に一枚とする両開土戸を開く。開口部周りに黒漆喰を施して対比をつける。質屋を営んでいた際に質物を納めたと伝わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010552"},{"id":"00010551","register_sub_id":"101","register_pk":"201125","name":"旧丸中横仲商店土蔵","kana":"きゅうまるなかよこなかしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市あら町2460他","lat":38.10093946,"lng":140.03844406,"geo_status":"db","era":"明治7年","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"06－0155","desc":"敷地の中央西寄りに、東西棟で質蔵と並び建つ。土蔵造二階建、平入で、屋根は置屋根形式とする。外壁は漆喰塗を基調とし、北面壁と四周の鉢巻を黒漆喰として対比をつける。南面には上下階に各三箇所の掛子塗の開口部を開き、高い左官技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010551"},{"id":"00010726","register_sub_id":"101","register_pk":"201561","name":"旧山寺ホテル","kana":"きゅうやまでらほてる","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市大字山寺字南院4278","lat":38.310715,"lng":140.434882,"geo_status":"db","era":"明治後期／大正5・昭和11改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鋼板葺及び鉄板葺、建築面積423㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0161","desc":"立石寺門前の川岸に建ち、中央の本館、西の居住部、東の新館と、二階建三棟を複合する。本館北面に当初の玄関を構え、仙山線開業頃に山寺駅側に唐破風造の玄関を設けた。新館二階は幾何意匠の立面を構成して時代的特徴を示すなど、門前の歴史的風致に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010726"},{"id":"00014557","register_sub_id":"101","register_pk":"515099","name":"古勢起屋本館","kana":"こせきやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県尾花沢市大字銀山新畑字北412","lat":38.56968611,"lng":140.53155278,"geo_status":"db","era":"大正3年／昭和7年増築、令和4年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積218㎡","structure_material":"木造3階建","registered":"2023.08.07(令和5.08.07)","register_no":"06 - 0209","desc":"銀山温泉街の銀山川北岸に所在する木造三階建温泉旅館。入母屋造銅板葺で各階に庇を巡らす。一階表通り側に浴室を設ける当地旅館の典型。客室は元は床構え付和室を並べる。玄関及び塔屋状の構えと、銀山川を望む二・三階の縁は歴史的温泉街の風情を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014557"},{"id":"00006987","register_sub_id":"101","register_pk":"107969","name":"齋藤家住宅主屋","kana":"さいとうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県長井市館町北639-1","lat":38.10003349,"lng":140.03807197,"geo_status":"db","era":"江戸末期／大正後期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0104","desc":"通りに西面する平入の町家。切妻造茅葺で、背面を葺き降ろし、正面に鉄板葺下屋を設ける。木造つし２階建で、内部は田の字型に４室に間仕切り、通り側にミセ、背面側に座敷や居間を配する。正面の格子や、茅葺屋根、妻などに伝統的な外観をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006987"},{"id":"00006988","register_sub_id":"101","register_pk":"107970","name":"齋藤家住宅土蔵","kana":"さいとうけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市館町北639-1","lat":38.09990546,"lng":140.03806122,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0105","desc":"主屋の南方に位置する。切妻造鉄板葺の置屋根。土蔵造２階建、桁行１２ｍ梁間４．６ｍで、内部は桁行に２室に分ける。外壁は中塗で、正面とその周囲を黒漆喰塗、窓まわりを白漆喰塗とする。小屋は軸太の棟木と垂木から構成され、重厚な空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006988"},{"id":"00003053","register_sub_id":"101","register_pk":"104043","name":"山王くらぶ","kana":"さんのうくらぶ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県酒田市日吉町2-2-25","lat":38.91846966,"lng":139.83221724,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積603㎡","structure_material":"木造2階一部平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"06 － 0052","desc":"木造・２階建の和風建築で，道路側の西面を凝った意匠を軽快にまとめ，東西に細長い雁行状の形態で敷地奥に延び，土蔵造の座敷や数寄屋造の茶室等を接続する。地元で名棟梁として知られた佐藤泰太良の作品で，手の込んだ上質かつ丁寧なつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003053"},{"id":"00013019","register_sub_id":"101","register_pk":"368226","name":"四山楼蔵座敷","kana":"しさんろうくらざしき","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県山形市七日町二丁目163-1他","lat":38.25281111,"lng":140.34166111,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積103㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"06 － 0193","desc":"主屋東側に東西棟で建つ。桁行六間、梁間三間、土蔵造二階建、切妻造で、東、北、西面に下屋を設けて廊下とする。一階に設けた座敷は床に銘木を用い、格天井を張る。庭に面する北面は黒漆喰塗の掛子塗土戸で重厚に見せる。県内に多く見られる蔵座敷の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013019"},{"id":"00013018","register_sub_id":"101","register_pk":"368225","name":"四山楼主屋","kana":"しさんろうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市七日町二丁目163-1他","lat":38.25298333,"lng":140.34145556,"geo_status":"db","era":"明治44年／昭和33年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、金属板葺、建築面積432㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"06 － 0192","desc":"山形市の繁華街に位置する料亭。敷地中央に西面して建つ、木造二階建、寄棟造で、西面中央に玄関が突出する。一階は北面中央に設けた洋風意匠のホールの両側に客室を配し、二階は大振りの床、舞台を備えた大広間とする。近代山形の繁栄を伝える上質な料亭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013018"},{"id":"00000020","register_sub_id":"101","register_pk":"101010","name":"相馬屋主屋","kana":"そうまやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県酒田市日吉町1-2-20","lat":38.91941924,"lng":139.8332811,"geo_status":"db","era":"明治28頃","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積483㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"06 － 0003","desc":"相馬屋は江戸時代末期から続いた料亭で，主屋は明治27年の地震時の大火によって焼失した直後に，残った土蔵等を取り込んで建設したものである。店，広間，土蔵等を繋いだ複雑な構成は特異で，トコ棚を備えた各室に用いられている技能の水準も高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000020"},{"id":"00002736","register_sub_id":"101","register_pk":"103726","name":"千歳館客室ちとせ","kana":"ちとせかんきゃくしつちとせ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県山形市七日町四丁目107-2","lat":38.25390848,"lng":140.343079,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0044","desc":"敷地の東北隅に建つ。１０畳の前室と床棚を備える１５畳の主室を持ち，庭に向いた南側から東へと広縁を廻らす。西側には廊下を隔てて風呂を設けていた。棚奥と東・南面の広縁両端間に花頭窓を設け，欄間や障子などの細部意匠などにも見るべき点がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002736"},{"id":"00002735","register_sub_id":"101","register_pk":"103725","name":"千歳館主屋","kana":"ちとせかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県山形市七日町四丁目107-2他","lat":38.25393134,"lng":140.34279448,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積380㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0043","desc":"木造２階建。１階南北に中廊下を通し，西側を洋風，東側を和風とする。立面もこれに呼応し西面は線材を強調する洋風で中央に玄関ポーチを設ける。東面は庭に向いて純和風の構成である。料亭建築の好例であるとともに，和洋の意匠を併せ持つ特異な建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002735"},{"id":"00006982","register_sub_id":"101","register_pk":"107964","name":"長沼合名会社内蔵","kana":"ながぬまごうめいがいしゃうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.11261,"lng":140.036652,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0099","desc":"店舗兼主屋の土間北面に蔵前を介して接続する。桁行９．２ｍ梁間３．７ｍ規模の土蔵造２階建で、切妻造置屋根鉄板葺とする。南妻に掛子塗両開戸をたて、各階東側面に窓を開け、１、２階通しの掛子塗戸を建てる。家財等を納めた土蔵で、伝統的な屋敷構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006982"},{"id":"00006983","register_sub_id":"101","register_pk":"107965","name":"長沼合名会社新蔵","kana":"ながぬまごうめいがいしゃしんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.11281604,"lng":140.03657196,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0100","desc":"内蔵の北に南北棟で建つ。桁行１１ｍ梁間５．６ｍの土蔵造２階建、切妻造鉄板葺置屋根とする。外壁は漆喰仕上げで、腰板を張る。東面南寄りに扉口を開き、内部を板敷、壁板張とする。南面には庇を設け、１、２階とも２ヶ所の窓を設け、窓ごとに両開戸をたてる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006983"},{"id":"00006981","register_sub_id":"101","register_pk":"107963","name":"長沼合名会社店舗兼主屋","kana":"ながぬまごうめいがいしゃてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.112385,"lng":140.036728,"geo_status":"db","era":"天保9／昭和33改修","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0098","desc":"通りに南面する敷地の出入口付近に東を正面に建つ。切妻造とし、もと茅葺の鉄板葺で、越屋根を設ける。桁行２０ｍ梁間１０ｍと規模が大きい。内部は北側に土間、南にトコや神棚を備える座敷や仏間、納戸、茶の間など６室を配し、地域的な特色ある平面を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006981"},{"id":"00006980","register_sub_id":"101","register_pk":"107962","name":"鍋屋本店主屋","kana":"なべやほんてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市十日町1-573","lat":38.11211314,"lng":140.03695376,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、茅葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0097","desc":"店舗の背面に南北棟で建つ。切妻造平入茅葺で、桁行１８ｍ梁間６．７ｍ規模。東を正面とし中央南寄りに入口を設け、トコを構える座敷や居間を店舗側に、背面に台所などを配する。棟を違えて建つ店舗と主屋を一連の建築として構成する町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006980"},{"id":"00006979","register_sub_id":"101","register_pk":"107961","name":"鍋屋本店店舗","kana":"なべやほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市十日町1-573","lat":38.11224238,"lng":140.03695924,"geo_status":"db","era":"明治後期／昭和40頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、茅葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0096","desc":"十日町通りに北面して建つ、木造つし２階建。屋根茅葺とし、東面は切妻で漆喰壁に架構を見せ、西面は寄棟造として葺き降ろす。内部は、もとは床を設けたが、今は土間の一室とする。正面つし２階の格子や、落ち着きある茅葺など、伝統的な街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006979"},{"id":"00012096","register_sub_id":"101","register_pk":"352895","name":"錦屋内蔵","kana":"にしきやうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県東置賜郡川西町大字上小松字北十日町1509","lat":38.007695,"lng":140.046988,"geo_status":"db","era":"明治前期／昭和60年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、金属板葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"06-189","desc":"店舗兼主屋の東に西面して建つ。桁行三間梁間二間、土蔵造二階建、妻入。内部は一、二階とも一室で、二階の床板や壁板にケヤキ板を用い、仕上げがよく残る。外壁は漆喰塗、腰部モルタル仕上げで、目地を切り石積風にみせ、街道沿いの歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012096"},{"id":"00012095","register_sub_id":"101","register_pk":"352894","name":"錦屋店舗兼主屋","kana":"にしきやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県東置賜郡川西町大字上小松字北十日町1509","lat":38.007743,"lng":140.046889,"geo_status":"db","era":"江戸後期／明治前期増築、大正期・昭和50年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"06-188","desc":"店舗はつし二階建平入で、後方に平屋建の主屋を棟を直交して接続する。屋根は切妻造、茅葺。妻面に束や貫を現し、当地域の町家の特徴を示す。正面の下屋庇は失われているが、つし二階の虫籠窓は残る。茅葺の外観で地域の歴史的景観を良好に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012095"},{"id":"00011240","register_sub_id":"101","register_pk":"209075","name":"ニュー村尾浪漫館離れ","kana":"にゅーむらおろまんかんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県上山市新湯88-5他","lat":38.157494,"lng":140.273646,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積522㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"06－0176","desc":"敷地の中央にあり、池に面して入母屋造、セメント製桟瓦葺の五棟を配し、それぞれを渡廊下で結ぶ。外壁や庇など庭園からの見栄えに配慮するとともに、内部も座敷飾、欄間、障子戸、襖絵など、手の込んだ豪華な意匠とする。温泉街の繁栄と格式をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011240"},{"id":"00000121","register_sub_id":"101","register_pk":"101111","name":"能登屋旅館本館","kana":"のとやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県尾花沢市大字銀山新畑446","lat":38.56941396,"lng":140.53158751,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造3階建塔屋付，鉄板葺，建築面積333㎡","structure_material":"木造3階建塔屋付","registered":"1997.05.07(平成9.05.07)","register_no":"06 － 0006","desc":"銀山川と背後の急傾斜地に挟まれた狭隘な場所に立置する秘湯の里銀山温泉街にある老舗の温泉旅館で，銀山川に面して木造３階建，塔屋付きの外観を保つ。和風を基調としながら正面にバルコニー付きの玄関を持つなど洒落た外観意匠は広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000121"},{"id":"00000120","register_sub_id":"101","register_pk":"101110","name":"ホテル音羽屋本館","kana":"ほてるおとわやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県米沢市駅前2-1-40","lat":37.90956007,"lng":140.12663162,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造3階建，瓦葺，建築面積100㎡","structure_material":"木造3階建","registered":"1997.05.07(平成9.05.07)","register_no":"06 － 0005","desc":"木造３階建，入母屋造で，正面に千鳥破風の屋根を設ける。１階にアーチ状の出入り口や窓を設け，２階に出窓，３階には花頭窓風の窓を開き，隅柱等に色付けするなどの正面の賑やかな外観の意匠に特徴があり，米沢の駅前においてひときわ目を引く建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000120"},{"id":"00008808","register_sub_id":"101","register_pk":"162251","name":"山城屋旧館","kana":"やましろやきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県上山市湯町277他","lat":38.16024028,"lng":140.27681126,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積219㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0126","desc":"敷地中央に建ち、木造2階建、建築面積219㎡、寄棟造鉄板葺である。上下階とも、蔵王連峰を望む南東面に客室を配置し、周囲に廊下を廻らし、ガラス戸を建てて開放的につくる。2階建具に色ガラスを使うなど、瀟洒な外観の旅館建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008808"},{"id":"00008809","register_sub_id":"101","register_pk":"162252","name":"山城屋荷蔵","kana":"やましろやにぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県上山市湯町277他","lat":38.16025531,"lng":140.27697017,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、鉄板葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0127","desc":"旧館東側の通路沿いに建ち、桁行9.4ｍ梁間4.7ｍ、土蔵造2階建、切妻造妻入、置屋根式の瓦葺で、北面出入口に庇を付ける。外壁は漆喰塗で腰を簓子下見板張とし、窓枠などを漆喰塗で丁寧に仕上げる。温泉街の景観に風情を添えている","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008809"},{"id":"00008810","register_sub_id":"101","register_pk":"162253","name":"旅館よね本旅館棟","kana":"りょかんよねもとりょかんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県上山市沢丁421","lat":38.15516617,"lng":140.27475915,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積178㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0128","desc":"敷地中央に建ち、木造2階建、建築面積178㎡、寄棟造鉄板葺である。外壁は柱形をみせたモルタル塗で、1階は西隅を隅切してドリス式風の柱形をつくり、2階は丸窓を配し、また南面には入母屋造の玄関を構えるなど奇想の外観になる旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008810"},{"id":"00001558","register_sub_id":"101","register_pk":"102548","name":"足利銀行黒羽支店（旧黒羽銀行）","kana":"あしかがぎんこうくろばねしてん（きゅうくろばねぎんこう）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県大田原市黒羽向町32","lat":36.85997,"lng":140.116974,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積500㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"09 － 0025","desc":"明治末期頃，黒羽市街の中心部に建てられた。寄棟造・桟瓦葺，２階建で，下屋庇や大谷石積の張出し及び玄関ポーチを設ける。外壁は出桁造の２階軒まで黒漆喰塗とし，２階の鉄扉や１階正面の鉄格子など開口部を厳重に構える。重厚な土蔵造の銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001558"},{"id":"00003789","register_sub_id":"101","register_pk":"104779","name":"天海家住宅店舗","kana":"あまがいけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市嘉右衛門町５他","lat":36.38595881,"lng":139.73324319,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0092","desc":"旧例幣使街道に東面して建つ。桁行３間半梁間２間，切妻造，桟瓦葺，平入のたちの高い木造２階建店舗で，前面に奥行半間の下屋庇を設ける。隣地に接する北側の妻壁は凝灰岩の石積とし，屋根上まで建ち上げて卯建風にしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003789"},{"id":"00001885","register_sub_id":"101","register_pk":"102875","name":"五十畑荒物店店舗","kana":"いかはたあらものてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町11-4","lat":36.37892269,"lng":139.73360565,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0039","desc":"五十畑家は大正１２年創業で，現在の店舗はもと糸綿商佐山家が明治中期に建設したという。切妻造・平入，総２階建の土蔵造で，幅広の正面下屋庇が特色。外壁は漆喰塗であるが，両妻面は簓子下見板張とする。奥の住居とは１階奥中央の出入口で結ばれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001885"},{"id":"00001872","register_sub_id":"101","register_pk":"102862","name":"大島肥料店店舗","kana":"おおしまひりょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市大町字通大町56他","lat":36.391598,"lng":139.734848,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0026","desc":"大島家は江戸末期から肥料商を営んできた旧家で，店舗の見世蔵は棟札より初代元平が明治１５年に建設したことがわかる。西面して建つ切妻造・平入・２階建，正面下屋庇付の土蔵造。下屋両端の腰部石張や，２階の窓庇の鉄製装飾持送りに特色がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001872"},{"id":"00013683","register_sub_id":"101","register_pk":"505191","name":"太田家住宅稲荷社","kana":"おおたけじゅうたくいなりしゃ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市天明町字現石町2579-3","lat":36.31219722,"lng":139.57455833,"geo_status":"db","era":"明治14年頃","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積0.5㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 262","desc":"敷地北寄りに建つ。正面一間側面二間切妻造桟瓦葺妻入。土台に角柱を立て腰長押、内法長押を廻し組物は舟肘木。壁に菱格子を嵌め、正面扉は格子入の桟唐戸。屋根瓦は規模にあわせた小瓦で家紋入鬼瓦を据える。小規模ながら精巧な屋敷社。奥庭の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013683"},{"id":"00013684","register_sub_id":"101","register_pk":"505193","name":"太田家住宅表門及び石塀","kana":"おおたけじゅうたくおもてもんおよびいしべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2583-2他","lat":36.31203889,"lng":139.57489167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"表門 石造、間口2.4m、石塀 石造、総延長9.8m","structure_material":"表門 石造","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 263","desc":"見世蔵の南に建つ。石塀は延長九・八メートルで、基礎石上に切石積とし高さは三・九メートル。表門は石塀の中央に開けた間口二・四メートルの開口で、御影石の角柱を立て楣石を載せる。門扉は木製。繰形付楣石の両端に獅子彫刻を載せた特徴的な意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013684"},{"id":"00013679","register_sub_id":"101","register_pk":"505183","name":"太田家住宅中蔵","kana":"おおたけじゅうたくなかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2582-2","lat":36.31205833,"lng":139.57458889,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造一部木造2階建、瓦葺、建築面積76㎡","structure_material":"土蔵造一部木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 258","desc":"主屋の西に建つ。土蔵造二階建と棟を直交する木造二階建を接続させ一体とする。土蔵部分は漆喰塗で鉢巻を廻す。戸前は両開き戸で、内部は一階、二階とも板敷で壁に板を張る。木造部分は数寄屋風意匠を採り、使用人部屋や浴室を備える。敷地中央の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013679"},{"id":"00013680","register_sub_id":"101","register_pk":"505185","name":"太田家住宅西蔵","kana":"おおたけじゅうたくにしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2582-2","lat":36.31203889,"lng":139.57442778,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 259","desc":"中蔵の西に建つ。土蔵造二階建切妻造桟瓦葺で南北棟。東に下屋を付し土戸引分の戸口を二箇所とる。二階も東に土戸両開きの窓を二箇所開ける。外壁は漆喰塗で鉢巻まで塗込める。内部は一、二階とも二室で二階南室を畳敷とし他は板敷。敷地西辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013680"},{"id":"00013682","register_sub_id":"101","register_pk":"505189","name":"太田家住宅八幡社","kana":"おおたけじゅうたくはちまんしゃ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2583-2","lat":36.31195833,"lng":139.57465,"geo_status":"db","era":"明治14年頃","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.2㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 261","desc":"敷地南に位置。一間社入母屋造銅板葺で、正面に千鳥破風及び唐破風造の向拝を付す。土台に丸柱を立て腰長押、内法長押を廻し組物は出組を詰組とする。擬宝珠高欄付の縁を正側面に廻す。虹梁や拳鼻の彫刻は精緻で要所に金具を打つ等小規模ながら精巧な屋敷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013682"},{"id":"00013678","register_sub_id":"101","register_pk":"505181","name":"太田家住宅見世蔵及び主屋","kana":"おおたけじゅうたくみせぐらおよびおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2582-2","lat":36.31203611,"lng":139.57483611,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 257","desc":"佐野市の中心部に位置。見世蔵は土蔵造二階建切妻造桟瓦葺で正面に下屋を通す。二階は出桁造で軒裏まで塗込め、棟を高く積む等店蔵の特徴を示す。主屋は棟を直交させて西に接続する。二階建切妻造桟瓦葺で南に下屋を付す。重厚な見世蔵が通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013678"},{"id":"00013681","register_sub_id":"101","register_pk":"505187","name":"太田家住宅南蔵","kana":"おおたけじゅうたくみなみぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2583-1","lat":36.31193889,"lng":139.57439167,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 260","desc":"敷地南西隅に建つ。土蔵造二階建、切妻造桟瓦葺で東に下屋を付し、板戸片引を建てる。二階の東と南に窓を開ける。鉢巻を二重にするなど重厚な外観を持つ。内部は一、二階とも一室で板敷に漆喰壁。小屋組は登梁と二重梁を交互に架ける。西辺の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013681"},{"id":"00008639","register_sub_id":"101","register_pk":"149360","name":"大谷好美館","kana":"おおやこうびかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県鹿沼市今宮町字西中町1609-4","lat":36.5649263,"lng":139.74538535,"geo_status":"db","era":"明治後期／昭和前期・平成18年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鉄板葺、建築面積61㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0193","desc":"神社への参道に西面して建つ。木造2階建、下見板張とする写真館。入母屋造妻入鉄板葺で、正面にポーチを付け、妻壁には植物模様や「美」の文字を飾る。1階を和室や待合室、2階を広い撮影室とする。屋根に採光のための天窓を設け、写真館らしい外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008639"},{"id":"00001887","register_sub_id":"101","register_pk":"102877","name":"雅秀店舗","kana":"がしゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町3-2","lat":36.37890142,"lng":139.731598,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0041","desc":"旧例幣使街道の西木戸があった幸来橋の東にある。南面して建ち，切妻造・桟瓦葺，総２階建の土蔵造。外壁は黒漆喰塗で，両妻面とも簓子下見板張，２階窓には観音扉を備える。２階は中央で左右に間仕切り，座敷とする。高い棟積，大柄な影盛など豪壮な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001887"},{"id":"00010915","register_sub_id":"101","register_pk":"208886","name":"加登屋旅館別館","kana":"かどやりょかんべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県那須塩原市板室字塩沢854他","lat":37.067433,"lng":139.923706,"geo_status":"db","era":"昭和12頃／昭和48改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積33㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"09-0222","desc":"本館と悠仙閣の間に挟まれて建つ。木造三階建で、各階とも客室となる。内部は簡素ながらも座敷飾を備えた和室を並べる一方、壁面をドイツ壁風の仕上げとして、側面には上下窓を持つなど外観には洋風意匠を織り交ぜ、当時の流行を取り入れた旅館建築となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010915"},{"id":"00010914","register_sub_id":"101","register_pk":"208885","name":"加登屋旅館本館","kana":"かどやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県那須塩原市板室字塩沢854他","lat":37.067517,"lng":139.923769,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積114㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"09-0221","desc":"加登屋旅館は、板室温泉の老舗旅館のひとつ。本館は木造三階建で、一階を帳場などの事務空間とし、二階と三階は西に廊下を通し、六畳間の客室を並べ、端の部屋には床構えを設ける。東正面には木製手摺を張り出して、湯治場としての温泉街の情緒を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010914"},{"id":"00010916","register_sub_id":"101","register_pk":"208887","name":"加登屋旅館悠仙閣","kana":"かどやりょかんゆうせんかく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"栃木県","address":"栃木県那須塩原市板室字塩沢854他","lat":37.067367,"lng":139.923697,"geo_status":"db","era":"昭和27頃","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"09-0223","desc":"別館の南に接続して建つ。木造二階建で、一階を玄関と客室及び浴室、二階を客室とする。内外とも、随所に奇木を用いたり、円窓や変形六角形の下地窓を穿ったりするなど、数寄屋風の趣向を凝らした造形を見せ、温泉街の通りに対して洒脱な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010916"},{"id":"00007178","register_sub_id":"101","register_pk":"108160","name":"旧足利銀行栃木支店","kana":"きゅうあしかがぎんこうとちぎしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県栃木市万町15-25","lat":36.38292693,"lng":139.73443217,"geo_status":"db","era":"昭和9／平成17移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"09 － 0175","desc":"旧例幣使街道に東面して建つ。建築面積１１１㎡。切妻造鉄板葺の周囲にパラペットを立ち上げ、外観を陸屋根に見せる木造平屋建。正面中央に出入口を設け、その両脇にトスカナ式オーダー風の角柱を建てる。古典様式になる昭和前期の銀行建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007178"},{"id":"00016647","register_sub_id":"101","register_pk":"579131","name":"旧下野中央銀行喜連川支店店舗","kana":"きゅうしもつけちゅうおうぎんこうきつれがわしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県さくら市喜連川4341-1","lat":36.718092,"lng":140.026202,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積94㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"09 - 0278","desc":"奥州街道に西面して建つ旧銀行店舗。設計は大森茂。鉄筋コンクリート造平屋建でパラペットを付す。外観は八角形柱型を並べ、半円アーチ形や四葉形の窓を飾り、人造石とタイル貼の独特な外観を持つ。内部はカウンターや金庫室が残る。地域の近代化を象徴する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016647"},{"id":"00011864","register_sub_id":"101","register_pk":"354914","name":"旧土佐屋薬局座敷蔵・中蔵・奥蔵","kana":"きゅうとさややっきょくざしきぐら・なかぐら・おくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市本町2942","lat":36.313884,"lng":139.574063,"geo_status":"db","era":"明治10年頃／明治23年増築、平成15年改修","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積106㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"09-236","desc":"主屋の北側に建つ。敷地奥に奥蔵が建ち、一段棟を低くし中蔵が続き、座敷蔵は棟を直交し、主屋側に観音扉を開く。奥蔵は桁行六間と大規模で、一階に鉄板張で和紙の目張をした薬庫を設け、座敷蔵は拭漆仕上げの上質な造り。商家を構成する上で欠かせない土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011864"},{"id":"00011863","register_sub_id":"101","register_pk":"354913","name":"旧土佐屋薬局店舗兼主屋","kana":"きゅうとさややっきょくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市本町2942","lat":36.313696,"lng":139.574075,"geo_status":"db","era":"明治28年頃／昭和中期改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積136㎡、門及び塀付","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"09-235","desc":"旧日光例幣使街道沿いに南面する。正面を黒漆喰塗とし、蛇腹の軒や棟の影盛など重厚な外観を見せるが、脇の門塀は石積アーチ状の洋風意匠である。表庭に面した座敷は数寄屋風、二階表側の座敷は曲率の強い室床など趣向を凝らした意匠に見応えがある商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011863"},{"id":"00013225","register_sub_id":"101","register_pk":"366214","name":"旧南間ホテル別館（ましこ悠和館）","kana":"きゅうなんまほてるべっかんましこゆうわかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県芳賀郡益子町大字益子字向原4264-8","lat":36.46365556,"lng":140.11539444,"geo_status":"db","era":"昭和4年頃／昭和48年移築、平成31年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、金属板葺、建築面積298㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"09 － 0252","desc":"日光市湯元から町東部の現在地に移築した建物。入母屋造の主体部両端から入母屋造の翼部を突出したコの字形平面で、真壁造の外壁に、刎高欄や腕木庇などの和風意匠を巧みに取り入れた外観とする。客室の床に銘木を使用するなど、近代の和風ホテル建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013225"},{"id":"00005242","register_sub_id":"101","register_pk":"106230","name":"旧日光市庁舎本館","kana":"きゅうにっこうしちょうしゃほんかん","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県日光市中鉢石町999","lat":36.750759,"lng":139.607422,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造3階建、鉄板葺、建築面積2470㎡","structure_material":"木造3階建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0137","desc":"日光街道沿いに「大名ホテル」として建設される。間口４４ｍ，奥行１７ｍの木造３階建の主体部は正面モルタル塗，背面下見板張とし，大ぶりな破風を載せた左右翼部を正面に張出し中央を望楼風とした城郭風の造り。南に入母屋造，総３階建の付属棟を接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005242"},{"id":"00001879","register_sub_id":"101","register_pk":"102869","name":"好古壱番館（旧安達呉服店店舗）","kana":"こうこいちばんかん（きゅうあだちごふくてんてんぽ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市万町4-2","lat":36.38052155,"lng":139.73413965,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積56㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0033","desc":"蔵造の町並に点在する洋風建築のひとつ。もと呉服商の店舗で大正１２年の建設。木造２階建で，１階正面をポーチ状に張出し，銅板葺の寄棟マンサード屋根を架け，屋根窓を設ける。柱や扁平アーチ部を石張で石造風に仕上げるなど，大正期の意匠をよく表現する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001879"},{"id":"00003799","register_sub_id":"101","register_pk":"104789","name":"櫻井肥料店店舗","kana":"さくらいひりょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市万町15-17","lat":36.384018,"lng":139.734772,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積80㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0102","desc":"旧例幣使街道に東面して建つ。間口桁行７間半梁間３間，切妻造，桟瓦葺，平入の２階建大型町家で，前面に半間の下屋を設ける。南寄りに１間幅の通路をとり，その南側を板敷物置，北側をミセとする。南面のみ漆喰塗とし，１階に煉瓦造袖壁を建てるのも特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003799"},{"id":"00003802","register_sub_id":"101","register_pk":"104792","name":"櫻井肥料店煉瓦蔵","kana":"さくらいひりょうてんれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市万町15-17","lat":36.38400147,"lng":139.73448097,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造平屋建、瓦葺、建築面積12㎡","structure_material":"煉瓦造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0105","desc":"主屋の西南方に位置し，文庫蔵と向き合って建つ。桁行２間半梁間１間規模，寄棟造，桟瓦葺，平入の平屋建煉瓦造物置で，壁厚は煉瓦１枚積とする。小規模ながら，フランス積で，壁上部に煉瓦を抜いて千鳥模様を造りだすなど煉瓦積技法にも見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003802"},{"id":"00001881","register_sub_id":"101","register_pk":"102871","name":"佐藤家住宅店舗","kana":"さとうけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町14-2","lat":36.38001452,"lng":139.73392565,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0035","desc":"旧例幣使街道沿いに西面して建つ土蔵造の店舗。切妻造・平入，総２階建，正面下屋庇付で，軒は出桁造。外壁は黒漆喰塗になり，正面２階窓はやや縦長であるが，南妻面にも窓を設ける。全体に階高も高く，開口部も多くなっており，明治中期と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001881"},{"id":"00014735","register_sub_id":"101","register_pk":"518993","name":"三斗小屋温泉大黒屋旅館本館","kana":"さんどごやおんせんだいこくやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県那須塩原市板室字三斗小屋湯所919他","lat":37.13833889,"lng":139.94569167,"geo_status":"db","era":"明治2年頃／明治5年増築、大正前期・昭和前期・同中期・同54年改修","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積223㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"09 - 0273","desc":"那須岳中腹に位置する三斗小屋温泉の旅館。2階建の南北棟で北を寄棟造、南を切妻造とし、屋根は鉄板葺とする。北に玄関と広間、南に風呂を配し、これらを結ぶ中廊下を通して、周囲に客室を配す。建ちが低く古式で、近世由来の温泉宿の様相を留める旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014735"},{"id":"00003803","register_sub_id":"101","register_pk":"104793","name":"下都賀酒造協同組合事務所","kana":"しもつがしゅぞうきょうどうくみあいじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県栃木市万町25-16","lat":36.38101803,"lng":139.73794355,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積104㎡","structure_material":"木骨石造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0106","desc":"栃木市街の東部に位置する。桁行６間梁間５間，寄棟造，桟瓦葺の２階建事務所建築で，正面中央に洗出し仕上げの玄関ポーチを突き出す。２階中央に破風型の庇を付けるほかは縦長窓を整然と並べ，軒蛇腹や胴蛇腹を石で造り出す。木骨石造事務所建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003803"},{"id":"00001875","register_sub_id":"101","register_pk":"102865","name":"下野新聞社栃木支局","kana":"しもつけしんぶんしゃとちぎしきょく","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県栃木市万町7-5","lat":36.382347,"lng":139.73468,"geo_status":"db","era":"文久1","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0029","desc":"もとは「毛惣」で知られた肥料商の２代目毛塚惣八が建設した見世蔵で，墨書から大工棟梁は地元の鈴木七右衛門とわかる。切妻造・平入，総２階建，正面は下屋庇付で軒を出桁造，黒漆喰塗とする重厚な土蔵造で，正面２階の窓は縦長の古い形式をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001875"},{"id":"00001882","register_sub_id":"101","register_pk":"102872","name":"関根家住宅店舗","kana":"せきねけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市倭町11-4","lat":36.37900204,"lng":139.73362872,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積46㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0036","desc":"洋風店舗建築のひとつで，明治から昭和初期まで煙草卸売商を営んでいた。大正１１年の建設で，タイル張２階建，桟瓦葺。正面と両側面のパラペットを高く上げ，正面壁面は柱，縦長窓，装飾などが左右対称に整然と配され，大正期のセセッション風意匠が目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001882"},{"id":"00001878","register_sub_id":"101","register_pk":"102868","name":"大二商店店舗","kana":"だいにしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市万町4-3","lat":36.3806508,"lng":139.73416251,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0032","desc":"旧例幣使街道沿いに西面し，山本有三ふるさと記念館の少し南に建つ。もと糸綿商を営んだ屋号釜藤の見世蔵。規模は桁行３間半・梁間３間で，切妻造・平入，総２階建，正面下屋庇付の土蔵造。高さを低く押さえ，２階窓の形式も古風で，明治初期と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001878"},{"id":"00002754","register_sub_id":"101","register_pk":"103744","name":"高木会館","kana":"たかぎかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県那須塩原市本町5-19","lat":36.97023,"lng":140.058197,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造2階建、瓦葺、建築面積116㎡","structure_material":"石造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"09 － 0053","desc":"黒磯初の銀行の本店建築で，現在はレストランなどに活用されている。２階建で，切妻造・桟瓦葺，外壁は正面が芦野石，他が大谷石である。重厚な石積を基調としながら，軽快な櫛形風ペディメントやアーチ型飾りを備えるなど，町並のシンボル的存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002754"},{"id":"00003794","register_sub_id":"101","register_pk":"104784","name":"舘野家住宅店舗","kana":"たてのけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県栃木市泉町2-32","lat":36.38451726,"lng":139.73418211,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積83㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0097","desc":"旧例幣使街道に東面して建つ。桁行７間梁間４間半規模，寄棟造，鉄板葺の木造２階建店舗で，外観はヴェランダや連アーチの窓を配するなど洋風に見せる。店舗内部は土間と１２畳の帳場から成る和風店舗のつくりで，２階南側の１室のみを洋室に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003794"},{"id":"00003798","register_sub_id":"101","register_pk":"104788","name":"舘野家住宅鼻緒蔵","kana":"たてのけじゅうたくはなおぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市泉町2-32","lat":36.38445317,"lng":139.73385122,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0101","desc":"主屋の西南方に位置し，南北棟で建つ。切妻造，桟瓦葺，平入の２階建土蔵で，桁行５間半梁間３間と大きく，外周廻りを簓子下見板張とする。墨書から，施主「舘野平兵衛」，大工「早川辰造」が判明する。舘野家の最盛期の生業を示す遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003798"},{"id":"00001894","register_sub_id":"101","register_pk":"102884","name":"塚田家住宅銘木蔵","kana":"つかだけじゅうたくめいぼくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37807674,"lng":139.73073521,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積152㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0048","desc":"屋敷地の南辺に建つ切妻造・桟瓦葺，東西棟の巨大な倉庫建築。北面の庭側に吹放し下屋庇を備え，西面は落棟・入母屋屋根とする。外壁は東・南・西の３面が白漆喰塗で，北面の庇上は簓子下見板張になる。材木問屋としての建築構成上，根幹をなす存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001894"},{"id":"00001896","register_sub_id":"101","register_pk":"102886","name":"塚田歴史伝説館事務室、売店及び休憩所","kana":"つかだれきしでんせつかんじむしつ、ばいてんおよびきゅうけいじょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.378429,"lng":139.73122559,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積180㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0050","desc":"屋敷地東辺に建ち，墨書より大正５年の建設とわかる。いずれも２階建で，桟瓦葺屋根の東西に長大な建築。３つの建物に巧みに連結した構成で，破風や窓が効果的に配され，変化に富む外観となっている。現在は，一般公開のための管理施設として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001896"},{"id":"00001895","register_sub_id":"101","register_pk":"102885","name":"塚田歴史伝説館展示館","kana":"つかだれきしでんせつかんてんじかん","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37854004,"lng":139.73107907,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0049","desc":"塚田家は昭和５４年より土蔵群を中心として邸内を一般公開している。展示館は邸内で最も古い土蔵。主屋の南辺に建ち，南北棟で切妻造・桟瓦葺，東面に吹放し下屋庇を付け，巴波川側の西面は２階に５つの鉄格子入窓を軽快に配し，整った意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001895"},{"id":"00001897","register_sub_id":"101","register_pk":"102887","name":"塚田歴史伝説館人形山車・銘木展示館（旧荷蔵）","kana":"つかだれきしでんせつかんにんぎょうだし・めいぼくてんじかん（きゅうにぐら）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37833649,"lng":139.73096897,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積322㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0051","desc":"屋敷地のほぼ中央に建つＬ字型平面の２階建倉庫。桟瓦葺屋根で覆い，基本的には真壁造で，外壁の一部を簓子下見板張とする。小屋組はキングポストトラスで，明治４２年の上棟である。中央に通路をもち，もとは荷蔵であったが，現在は展示施設として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001897"},{"id":"00001889","register_sub_id":"101","register_pk":"102879","name":"毛塚紙店店舗","kana":"てづかかみてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町10-3","lat":36.37821831,"lng":139.73352958,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0043","desc":"江戸中期より紙商を営んだ老舗で，明治期には県内有数の紙問屋となった。店舗は西面して建ち，小屋梁墨書から明治４１年の上棟と判明。切妻造・平入の２階建，正面下屋庇付の形式で，黒漆喰塗，出桁造で３重蛇腹の軒，高い箱棟など，重厚な意匠の見世蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001889"},{"id":"00013041","register_sub_id":"101","register_pk":"368230","name":"寺岡糸店石蔵","kana":"てらおかいとてんいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.312975,"lng":139.57436667,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積73㎡","structure_material":"石造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0248","desc":"敷地北辺の中央に南面して建つ。石造平屋建、切妻造桟瓦葺で、正面に庇を付す。外部は大谷石積を現して鉢巻二段を廻し、正面入口は鉄製戸を引分ける。内部は小幅板を等間隔に張り、小屋はトラス組とする。糸問屋の歴史を伝える原糸貯蔵用の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013041"},{"id":"00013042","register_sub_id":"101","register_pk":"368348","name":"寺岡糸店大門","kana":"てらおかいとてんおおもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.31257222,"lng":139.57451667,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、間口3.1m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0249","desc":"店舗東側に建つ資材搬入に用いた門。木製、高さ3・6メートル、方形の木製門柱一対を間口3・1メートルで立て、木製の両開戸を備える。門柱両脇に延びる袖塀は、基礎を花崗岩の延石、屋根を金属板葺とした板塀。店舗と調和した街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013042"},{"id":"00013039","register_sub_id":"101","register_pk":"368229","name":"寺岡糸店主屋","kana":"てらおかいとてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.31273889,"lng":139.57428333,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0246","desc":"店舗後部の西側に接続して建つ、木造２階建、寄棟造桟瓦葺の主屋。南面東寄りに入母屋造の玄関を構え、上下階とも四周に下屋を廻す。外壁は真壁漆喰塗で腰を下見板張とする。内部は一階を書院風、二階を数寄屋風に仕上げる。瀟洒な屋敷景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013039"},{"id":"00013038","register_sub_id":"101","register_pk":"368346","name":"寺岡糸店店舗","kana":"てらおかいとてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.31264722,"lng":139.57442222,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積206㎡","structure_material":"木造2階一部平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0245","desc":"市街地中心部にある商家。店舗は街道に南面して建つ寄棟造桟瓦葺で、正面に下屋を付し、背面にコの字形の居住部が接続する。外壁は漆喰塗で腰を下見板張とする。内部前寄りの店舗部分は２層吹抜とした開放的なつくり。重厚な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013038"},{"id":"00013040","register_sub_id":"101","register_pk":"368347","name":"寺岡糸店文庫蔵","kana":"てらおかいとてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.31281667,"lng":139.57424167,"geo_status":"db","era":"明治7年／昭和8年頃改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0247","desc":"主屋北西に接続し、南北棟で建つ。土蔵造二階建、切妻造桟瓦葺で、南面に蔵前を付す。外壁は人造石洗出しで石積風に仕上、鉢巻二段を廻し、正面入口は漆喰塗戸を引分ける。内部は漆喰塗で、登梁形式の小屋組とする。敷地西辺の屋敷構えの一角を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013040"},{"id":"00001886","register_sub_id":"101","register_pk":"102876","name":"中田家住宅店舗","kana":"なかたけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県栃木市倭町316","lat":36.37879507,"lng":139.73323793,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0040","desc":"旧例幣使街道沿いに東面して建つ。切妻造・平入，総２階建，正面下屋庇付の土蔵造店舗で，江戸末期と推定。桁行５間と規模が大きく，梁間も３間あるため棟が高くなり，黒漆喰塗の外壁と相俟って重厚感がある。鉄格子入の２階窓は小さく，古めかしい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001886"},{"id":"00004921","register_sub_id":"101","register_pk":"105911","name":"日光金谷ホテル観覧亭（竜宮）","kana":"にっこうかなやほてるかんらんてい（りゅうぐう）","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.75156572,"lng":139.6047834,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、銅板葺、建築面積172㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0129","desc":"本館南方の高台に位置し，冬場にはスケートリンクになる池に面して南北棟で建つ。桁行５間，梁間２間半の規模，入母屋造，銅板葺の木造２階建で，入側柱には奇木を用いた凝った造りとし，周囲に下屋を廻し，北方の展望閣に向けて渡り廊下を下屋から延ばす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004921"},{"id":"00004920","register_sub_id":"101","register_pk":"105910","name":"日光金谷ホテル新館","kana":"にっこうかなやほてるしんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.75208735,"lng":139.60339868,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積503㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0128","desc":"本館の北西方に建つ。桁行１８間半，梁間８間規模，入母屋造，鉄板葺の木造２階建で，外壁は下見板張とし，胴蛇腹位置に瓔珞飾りと擬宝珠高欄を廻す。１階に無柱のバンケットホールを設け，小屋トラスから鉄棒で２階床を吊る特異な構造を有するのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004920"},{"id":"00004922","register_sub_id":"101","register_pk":"105912","name":"日光金谷ホテル展望閣","kana":"にっこうかなやほてるてんぼうかく","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.75170305,"lng":139.60460003,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積62㎡、渡廊下付","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0130","desc":"観覧亭（竜宮）の北方，高台崖際に建ち，観覧亭とは渡り廊下で繋がれる。桁行４間半，梁間２間の規模，東西棟，入母屋造，銅板葺の木造平屋建で，内部は化粧屋根裏とし，小壁下に内法長押を廻す。展望に配慮した吹き放ちの開放的なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004922"},{"id":"00004923","register_sub_id":"101","register_pk":"105913","name":"日光金谷ホテル別館","kana":"にっこうかなやほてるべっかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.75251726,"lng":139.60403241,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、銅板葺、建築面積423㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0131","desc":"本館の北東に建つ。桁行１６間，梁行８間規模，木造３階建の客室棟で，南面に唐破風造の車寄を付け，外観は真壁造に見せ，屋根は八棟造風に賑やかにつくる。久米権九郎設計になる和風建築で，構造は組立柱等を用いた久米独自の耐震木構法による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004923"},{"id":"00004919","register_sub_id":"101","register_pk":"105909","name":"日光金谷ホテル本館","kana":"にっこうかなやほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.7521656,"lng":139.60397516,"geo_status":"db","era":"明治26／昭和11増改造","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積1395㎡","structure_material":"木造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0127","desc":"明治２６年開業時の木造２階建を昭和１１年に地面を掘り下げて３階建とする。東を正面としたＬ字形平面で，１階にフロントロビーとバー，２階に食堂と７客室，３階に１７客室等を配し，内部に和風意匠を採り入れる。近代日光のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004919"},{"id":"00005243","register_sub_id":"101","register_pk":"106231","name":"日光物産商会店舗","kana":"にっこうぶっさんしょうかいてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市上鉢石町1026他","lat":36.75307106,"lng":139.605225,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、鉄板葺、建築面積233㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0138","desc":"日光二社一寺の門前に位置し，桁行２２ｍ，梁間１１ｍ規模の商業建築。木造２階建，入母屋造とし，２階に三斗組と蟇股を配した高欄を廻らし，妻面に琴柱花頭窓を穿ち，妻飾には二重虹梁大瓶束笈形の架構を見せるなど，寺院建築の細部を随所に取り入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005243"},{"id":"00003792","register_sub_id":"101","register_pk":"104782","name":"野口栄三商店店舗及び主屋","kana":"のぐちえいぞうしょうてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市泉町2-27","lat":36.38527083,"lng":139.73405838,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、鉄板及び瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0095","desc":"旧例幣使街道に東面して建つ。店舗は，桁行３間梁間２間半，南北棟，切妻造，鉄板葺の平入２階建で，前面に半間の下屋庇を差し出す。主屋は，桁行４間梁間２間，東西棟，切妻造，桟瓦葺の２階建で，南面に１間幅の下屋庇を設け店舗土間からの通り庭とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003792"},{"id":"00003793","register_sub_id":"101","register_pk":"104783","name":"野口栄三商店土蔵","kana":"のぐちえいぞうしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市泉町2-27","lat":36.38525993,"lng":139.73392255,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0096","desc":"主屋の西方に中庭を介して東西棟で建つ。桁行３間梁間３間，切妻造，桟瓦葺の妻入２階建土蔵で，東妻面に庇を差し出して蔵前をとる。墨書から大工「早川助造」が判明。もと美術小間物商内田家の荷蔵で，店舗及び主屋とともに当地町家の構えをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003793"},{"id":"00004914","register_sub_id":"101","register_pk":"105904","name":"原田家住宅店舗","kana":"はらだけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市通6-3225-1","lat":36.33807401,"lng":139.441406,"geo_status":"db","era":"大正9頃／昭和53曳家","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0122","desc":"旧国道５０号沿いに北面して建つ。桁行３間半，梁間２間半の規模，切妻造桟瓦葺，平入の木造２階建で，正面に半間の下屋をかけ，外壁は下見板張とする。明治から昭和初期に多く建築された出桁造の店舗の形式を良く残し，往時の通りの様子を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004914"},{"id":"00008641","register_sub_id":"101","register_pk":"149362","name":"福田家住宅奥座敷","kana":"ふくだけじゅうたくおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県鹿沼市上材木町1827他","lat":36.56935215,"lng":139.747925,"geo_status":"db","era":"明治後期／昭和20年頃移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0195","desc":"主屋の東に渡り廊下を介して続く。桁行7.4ｍ梁間5.7ｍ、木造2階建、東西棟の切妻造桟瓦葺。1、2階とも座敷2室を東西に並べ、南・西面に縁をまわし、主座敷には上質な座敷飾りを備える。開放的で、品格のある近代の接客空間をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008641"},{"id":"00008640","register_sub_id":"101","register_pk":"149361","name":"福田家住宅店棚及び主屋","kana":"ふくだけじゅうたくみせだなおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県鹿沼市上材木町1827他","lat":36.56926887,"lng":139.74777033,"geo_status":"db","era":"江戸末期／明治中期・大正前期増築・昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積221㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0194","desc":"旧鹿沼宿に位置し、旧例幣使街道に西面する。間口9.6ｍの木造二階建、切妻造の店棚と、東背面に続く木造平屋建、寄棟造の主屋からなる。桟瓦葺。正面に土間の深い銅板葺下屋を付け、その上部に格子窓を広く構え、落ち着きのある商家の佇まいをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008640"},{"id":"00001888","register_sub_id":"101","register_pk":"102878","name":"丸三家具店店舗","kana":"まるさんかぐてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町10-3","lat":36.37827466,"lng":139.73349938,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0042","desc":"切妻造・平入，２階建，正面下屋庇付，黒漆喰塗，出桁造・３重蛇腹の軒など，北隣に建つ明治４１年上棟の毛塚紙店店舗とほどんど同じ形式であるが，桁行３間と規模が半間小さい。横長の２階窓や高い箱棟，大柄な影盛など，明治後期の特色をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001888"},{"id":"00004916","register_sub_id":"101","register_pk":"105906","name":"柳田家住宅事務所","kana":"やなぎだけじゅうたくじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市通6-3226-1他","lat":36.33809686,"lng":139.44122783,"geo_status":"db","era":"明治24／昭和53曳家","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積181㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0124","desc":"当初は店舗兼住宅で，正面に下屋が付く切妻造桟瓦葺，平入木造２階建の店舗である。背面に桟瓦葺の木造平屋建の旧住宅が続く。外壁は漆喰塗と下見板張を基本とし，正面窓下を御影石等で飾る。隣地の原田家住宅店舗と共に織物産業隆盛期の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004916"},{"id":"00004917","register_sub_id":"101","register_pk":"105907","name":"柳田家住宅倉庫","kana":"やなぎだけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市通6-3226-1他","lat":36.33818576,"lng":139.44108434,"geo_status":"db","era":"大正初期／昭和53曳家","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0125","desc":"敷地北西隅に建つ切妻造桟瓦葺の土蔵造２階建，腰部分を石積とする。東面平壁に入口を設け，両妻壁各階中央に窓を設ける。外壁は漆喰塗とし，北面及び西面を下見板張とする。当初は西蔵と呼ばれ，事務所，表門と並んで旧国道５０号線沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004917"},{"id":"00001876","register_sub_id":"101","register_pk":"102866","name":"山本有三ふるさと記念館南棟","kana":"やまもとゆうぞうふるさときねんかんなんとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市万町5-3","lat":36.38103735,"lng":139.7343091,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0030","desc":"旧栃木宿のほぼ中央，旧例幣使街道沿いに西面して建つ。北棟と屋根を共有するが，北棟より先の建設である。切妻造・平入，総２階建，正面下屋庇付，黒漆喰塗の重厚な土蔵造。正面２階の窓はやや縦長で観音開扉を有し，背面には平屋建の居住棟が連続している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001876"},{"id":"00001877","register_sub_id":"101","register_pk":"102867","name":"山本有三ふるさと記念館北棟","kana":"やまもとゆうぞうふるさときねんかんほくとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市万町5-3","lat":36.38107455,"lng":139.734306,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0031","desc":"北棟は南面の柱が南棟壁面に組み込まれており，南棟より少し遅れての増築と推定。規模や形式は南棟とほぼ同じであるが，軒廻りや両側戸袋付の正面２階の横長窓など，意匠に変化をもたせ，巧みに処理している。とくに１階内部は土間と帳場の構えがよく残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001877"},{"id":"00000750","register_sub_id":"101","register_pk":"101740","name":"横山郷土館麻蔵","kana":"よこやまきょうどかんあさぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町2-16","lat":36.38141784,"lng":139.73245178,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造２階建，瓦葺，建築面積66㎡","structure_material":"石造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"09 － 0008","desc":"主屋の北側に建つ。麻は地元の特産品で，舟運による関連製品の売買で栄えた付近一帯には多数の蔵が残る。なかでもこの蔵は，比較的に大規模な石造の蔵としてひときわ目立つ存在。窓の意匠や小屋のトラス等には，洋風建築からの影響がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000750"},{"id":"00000749","register_sub_id":"101","register_pk":"101739","name":"横山郷土館店舗及び住居","kana":"よこやまきょうどかんてんぽおよびじゅうきょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町2-16","lat":36.38127655,"lng":139.73240092,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造２階建，瓦葺，建築面積256㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"09 － 0007","desc":"横山家は巴波川の舟運を利用して苧麻問屋を営み栄えた家で，川沿いの道路に面して広い屋敷地を構える。東面して接道する主屋は，前面を店舗，後方を住宅とし，正面をつし２階の町家風にした特徴あるつくりになる。店舗内部は北半を問屋，南半を銀行とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000749"},{"id":"00000751","register_sub_id":"101","register_pk":"101741","name":"横山郷土館文庫蔵","kana":"よこやまきょうどかんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町2-16","lat":36.38120732,"lng":139.73240798,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"石造２階建，瓦葺，建築面積66㎡","structure_material":"石造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"09 － 0009","desc":"主屋を挟み麻蔵と対称の位置にあり，独特の屋敷構えと景観を形成する石造の蔵。石材は，県内鹿沼市で産する深岩石と呼ばれる凝灰岩。つくりは麻蔵と似るが，軒を煉瓦積みとすることや１・２階間の石材の色をかえるなど，意匠により細かな配慮がなされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000751"},{"id":"00001880","register_sub_id":"101","register_pk":"102870","name":"綿忠はきもの店店舗","kana":"わたちゅうはきものてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県栃木市万町4-1","lat":36.38038931,"lng":139.73409055,"geo_status":"db","era":"安政3","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0034","desc":"綿忠は江戸後期創業という商家で，店舗は小屋梁の墨書から安政３年５月の上棟とわかる。桁行３間・梁間２間半と小規模で，通り土間が奥の住居棟まで続く。総２階建，正面下屋庇付の土蔵造で，全体に階高が低く，２階の縦長窓など幕末期の意匠がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001880"},{"id":"00000755","register_sub_id":"101","register_pk":"101745","name":"伊香保観光ホテル","kana":"いかほかんこうほてる","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県渋川市伊香保町伊香保字甲境沢550-1","lat":36.49866549,"lng":138.92455426,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造３階建，瓦葺一部鉄板葺，建築面積1874㎡","structure_material":"木造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"10 － 0028","desc":"明治の初頭より居留外国人の間で温泉場として名が知られていた伊香保の玄関口に位置する外国人向けホテル。外国人を意識した五重塔風の塔屋が特徴。木造３階建、一部ＲＣ造地下室付きで、正門からの脇道を跨ぐかたちで大食堂を配置し、三方にテラスを付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000755"},{"id":"00002016","register_sub_id":"101","register_pk":"103006","name":"石坂家住宅土蔵","kana":"いしざかけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県渋川市下ノ町2467-1","lat":36.49598063,"lng":139.00364059,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0058","desc":"桁行７間半，梁間４間規模，東西棟，寄棟造，桟瓦葺，平入の２階建土蔵で，南面に３箇所の引戸口を設ける。内部は桁行２間半づつ３室に分け，中央室に階段を付ける。石坂家が質屋を営んでいた時の質蔵でもあり，主屋とともに当家の繁栄振りを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002016"},{"id":"00015401","register_sub_id":"101","register_pk":"533416","name":"江原本家上毛倉庫一号棟","kana":"えばらほんけじょうもうそうこいちごうとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県前橋市表町二丁目25-2","lat":36.38461667,"lng":139.07346111,"geo_status":"db","era":"昭和24年／平成2年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積331㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0363","desc":"ＪＲ前橋駅の北口正面に位置し、かつて繭や生糸を保管した倉庫業の営業倉庫。敷地南東に建つ鉄筋コンクリート造切妻造桟瓦葺、外壁モルタル塗仕上で鉢巻を廻らし、高窓に鉄扉を付す。小屋組は木造のキングポスト・トラス。土蔵風の外観が歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015401"},{"id":"00015403","register_sub_id":"101","register_pk":"533418","name":"江原本家上毛倉庫三号煉瓦棟","kana":"えばらほんけじょうもうそうこさんごうれんがとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県前橋市表町二丁目25-2","lat":36.38521944,"lng":139.07328889,"geo_status":"db","era":"明治29年／昭和22年頃・平成元年・同30年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積300㎡","structure_material":"煉瓦造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0365","desc":"敷地北側に南面して建つ、かつて繭や生糸を保管した営業倉庫。煉瓦造二階建切妻造桟瓦葺で、外壁の四周に胴蛇腹と軒蛇腹を廻らし、アーチ窓を並べた長大な外観。小屋組は木造のキングポスト・トラスとする。２号煉瓦棟とともに敷地内最古の貴重な煉瓦造倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015403"},{"id":"00015404","register_sub_id":"101","register_pk":"533419","name":"江原本家上毛倉庫七号棟","kana":"えばらほんけじょうもうそうこななごうとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県前橋市表町二丁目25-2","lat":36.38470833,"lng":139.07319444,"geo_status":"db","era":"昭和25年／平成元年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積463㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0366","desc":"敷地中央に建つ米穀類用の営業倉庫。鉄筋コンクリート造切妻造桟瓦葺の南北棟で、東・西面に出入口を開け、外壁モルタル塗仕上。内部は一室の土間とし、上部に木造のキングポスト・トラスを現し、内壁は漆喰塗仕上で下部を竪板目板張。敷地内最大規模の倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015404"},{"id":"00015402","register_sub_id":"101","register_pk":"533417","name":"江原本家上毛倉庫二号煉瓦棟","kana":"えばらほんけじょうもうそうこにごうれんがとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県前橋市表町二丁目25-2","lat":36.38498333,"lng":139.07343889,"geo_status":"db","era":"明治29年／昭和22年頃・平成2年・平成21年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積335㎡","structure_material":"煉瓦造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0364","desc":"敷地東辺に西面して建つ、かつて繭や生糸を保管した営業倉庫。煉瓦造二階建切妻造平入桟瓦葺で、外壁四周に胴蛇腹と軒蛇腹を廻らし、長大な桁行にアーチ窓を並べた端正な外観。小屋組は木造キングポスト・トラス。明治期の前橋の繁栄を示す貴重な煉瓦造倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015402"},{"id":"00007724","register_sub_id":"101","register_pk":"108706","name":"荻野家住宅北蔵","kana":"おぎのけじゅうたくきたぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21147869,"lng":138.78232077,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0272","desc":"主屋の西に位置する。桁行１１ｍ梁間４．８ｍと比較的規模の大きな土蔵造２階建で、東西棟の切妻造桟瓦葺とする。外壁は白漆喰仕上げ。１階は二室に分け、東と南面に開口を設け、東面には両開の掛子塗戸を吊る。２階は一室で、トラス組架構を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007724"},{"id":"00007722","register_sub_id":"101","register_pk":"108704","name":"荻野家住宅主屋","kana":"おぎのけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.2114394,"lng":138.78247866,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0270","desc":"旧中山道脇往還に東面する短冊状の敷地の東寄りに位置する。木造２階建、起りのある入母屋造妻入桟瓦葺。１、２階とも二室に分かれ、１階はブツマなどの居室、２階にはトコや棚などを備える客間を配する。南面庭側を開放的に扱うなど軽快な近代和風建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007722"},{"id":"00007727","register_sub_id":"101","register_pk":"108709","name":"荻野家住宅新蔵","kana":"おぎのけじゅうたくしんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21153109,"lng":138.78199765,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0275","desc":"北蔵や南蔵などと少し離れた敷地西端に、南北棟で建つ。寄棟造桟瓦葺、桁行９．５ｍ梁間４．７ｍの土蔵造２階建。１階東面中央に出入口、２階に窓２ヶ所を開け、鉄扉を吊る。小屋はトラス組。西堀を介して旧道に面する敷地背後の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007727"},{"id":"00007728","register_sub_id":"101","register_pk":"108710","name":"荻野家住宅防火壁","kana":"おぎのけじゅうたくぼうかへき","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21145998,"lng":138.78255877,"geo_status":"db","era":"大正13頃／昭和25頃増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造一部鉄筋コンクリート造、延長18m","structure_material":"煉瓦造一部鉄筋コンクリート造","registered":"2009.08.07(平成21.08.07)","register_no":"10-0276","desc":"敷地北辺に主屋に接して築かれる。全長１３ｍ、高さ７．３ｍ、厚さ０．４３ｍの煉瓦造で、東側５．０ｍをＲＣ造で増築。主屋前寄りの長さ１．５ｍは１．４ｍほど高くし、棟を造り、ウダツ風に見せる。延焼防止に造られた防火壁で、地域の大火の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007728"},{"id":"00007723","register_sub_id":"101","register_pk":"108705","name":"荻野家住宅店蔵","kana":"おぎのけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21139233,"lng":138.78259828,"geo_status":"db","era":"明治後期／大正期・昭和45頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0271","desc":"旧脇往還に東面して建つ。桁行７．７ｍ梁間５．７ｍの平入土蔵造２階建、切妻造桟瓦葺で、正面に庇を付ける。外壁は白漆喰仕上げで、腰をモルタル洗い出し仕上げとする。正面は１階にもとは土戸をたて、２階に２ヶ所窓を開けた。凝った大棟のつくりは印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007723"},{"id":"00007725","register_sub_id":"101","register_pk":"108707","name":"荻野家住宅南蔵","kana":"おぎのけじゅうたくみなみぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21142532,"lng":138.78225672,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0273","desc":"北蔵の南に東西棟で並び建つ。桁行４．９ｍ梁間３．７ｍの土蔵造２階建、切妻造妻入桟瓦葺。外壁は白漆喰仕上げ。１階東面に両開の掛子塗戸を吊り、２階南面には窓を穿ち、鉄扉とする。内部は１、２階とも一室。大梁上に束を建て棟木を支持する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007725"},{"id":"00007726","register_sub_id":"101","register_pk":"108708","name":"荻野家住宅物置蔵及び長屋","kana":"おぎのけじゅうたくものおきぐらおよびながや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.2113836,"lng":138.78236443,"geo_status":"db","era":"明治後期／大正期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積46㎡","structure_material":"木造2階一部平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0274","desc":"敷地の南辺に位置し、南側の殿小路に面する。物置蔵は桁行７．６ｍ梁間２．８ｍの木造２階建、切妻造桟瓦葺。長屋は桁行１２ｍ梁間２．２ｍの木造平屋建で、物置蔵寄りに門口を開ける。小路側に腰モルタル洗い出しの白漆喰壁が連続し、重厚な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007726"},{"id":"00005409","register_sub_id":"101","register_pk":"106397","name":"金善ビル","kana":"かなぜんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町5-345","lat":36.411583,"lng":139.339294,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積94㎡、塔屋付","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0158","desc":"間口８．２ｍ，奥行９．１ｍ，地下１階地上４階建，塔屋付きの鉄筋コンクリート造ビルで，１階はたちを高く造り石張風とし，２階以上には白タイルを張り，玄関上方等にセセッション風装飾を付ける。地方都市における初期鉄筋コンクリート造事務所ビルの好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005409"},{"id":"00006976","register_sub_id":"101","register_pk":"107958","name":"旧勝山社煉瓦蔵","kana":"きゅうかつやましゃれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県前橋市本町2-3-8","lat":36.38989152,"lng":139.06963159,"geo_status":"db","era":"明治35／昭和28移築・昭和56改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積45㎡","structure_material":"煉瓦造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"10 － 0252","desc":"桁行８．８ｍ梁間５．１ｍ妻入の煉瓦造２階建で、屋根は切妻造桟瓦葺である。外壁の煉瓦はイギリス積で、鉢巻や窓まわりに土蔵風の意匠を見せる。正面出入口は後世の改修。小屋組はキングポスト・トラスである。軒が高く重厚な外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006976"},{"id":"00010919","register_sub_id":"101","register_pk":"208890","name":"旧館林二業見番組合事務所","kana":"きゅうたてばやしにぎょうけんばんくみあいじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県館林市本町二丁目1704","lat":36.24616,"lng":139.534414,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積195㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"10-0327","desc":"料亭と芸妓置屋の二業の旧組合事務所。木造二階建で通りに西面する。一階は事務室と座敷、二階は舞台を持つ畳敷の大広間をおく。通りに面する西面は入母屋造屋根の妻と唐破風造の玄関を見せ、二階には左右対称の切妻屋根を並べるなど、和風意匠で華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010919"},{"id":"00004926","register_sub_id":"101","register_pk":"105916","name":"旧松岡商店蔵","kana":"きゅうまつおかしょうてんくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町6-7","lat":36.41248859,"lng":139.33701314,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積29㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0129","desc":"敷地の北寄りに，事務所と主屋の間に東西棟で建つ。木造２階建の蔵で，切妻造，鉄板葺の置屋根を置く。道路に面する北壁面には各階に２つの窓を開く。南面に入口を設け，蔵前を置く。外壁はモルタル塗で，事務所や主屋と共に，創建時の様子を良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004926"},{"id":"00004925","register_sub_id":"101","register_pk":"105915","name":"旧松岡商店事務所","kana":"きゅうまつおかしょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町6-7","lat":36.4124459,"lng":139.337067,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0128","desc":"道路沿いに東面して建つ。表側の事務室２室と検反場を矩折に配し，寄棟屋根を南東隅で直交する木造平屋建。その南部に東西棟の切妻造，木造平屋建の荷受場が接続する。正面等に茶系のタイルを用いて洋風の外観を見せる商店建築で，窓脇のレリーフや丸窓が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004925"},{"id":"00004207","register_sub_id":"101","register_pk":"105197","name":"旧安田銀行担保倉庫（協同組合前橋商品市場倉庫）","kana":"きゅうやすだぎんこうたんぽそうこ（きょうどうくみあいまえばししょうひんいちばそうこ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県前橋市住吉町2-10-2","lat":36.39725576,"lng":139.07012121,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積693㎡","structure_material":"煉瓦造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"10 － 0118","desc":"群馬商業銀行附属前橋倉庫として建設。主として生糸等の担保用倉庫で，桁行３０間梁間６間規模，切妻造，桟瓦葺の煉瓦造２階建，イギリス積の２戸前倉庫。煉瓦は日本煉瓦製造製，階下２枚階上１枚半積で，木造床，小屋組は木造のキングポストトラスである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004207"},{"id":"00002005","register_sub_id":"101","register_pk":"102995","name":"小見家住宅（水村園）新蔵","kana":"こみけじゅうたく（みずむらえん）しんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.330818,"lng":139.003128,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0047","desc":"味噌蔵の北方に位置する桁行３間半，梁行２間規模，南北棟，切妻造，桟瓦葺，平入の２階建土蔵。棟高は一番高く，東面に観音扉を付ける。内部は現在は南妻面に階段を取付け，２階の西と北の２面に造りつけの茶箱を配する。茶舗の歴史を物語る土蔵として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002005"},{"id":"00002006","register_sub_id":"101","register_pk":"102996","name":"小見家住宅（水村園）前蔵","kana":"こみけじゅうたく（みずむらえん）まえぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.33089644,"lng":139.00312457,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0048","desc":"敷地の北西隅に位置し，新蔵の北妻面に接して建つ。桁行２間半，梁行は新蔵と同じ２間で，南北棟，切妻造，桟瓦葺，平入とする。棟は新蔵よりも低く，東面の入口は引戸としてより簡素なつくりとし，防火帯としての土蔵群の北端を押さえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002006"},{"id":"00002008","register_sub_id":"101","register_pk":"102998","name":"小見家住宅（水村園）レンガ蔵","kana":"こみけじゅうたく（みずむらえん）れんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.330791,"lng":139.003174,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"煉瓦造2階建、瓦葺、建築面積53㎡","structure_material":"煉瓦造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0050","desc":"敷地の東辺沿い，着物蔵・味噌蔵・新蔵に向きあう位置に建つ。桁行７間半，梁行２間の規模で，東面は煉瓦造防火壁を利用し，西面は木柱を建てて吹放ちとし，南北棟の桟瓦葺寄棟屋根を架ける。煉瓦造と木造の混合構造による数少ない事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002008"},{"id":"00005926","register_sub_id":"101","register_pk":"106911","name":"島田商店旧石蔵","kana":"しまだしょうてんきゅういしぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.409115,"lng":139.336197,"geo_status":"db","era":"昭和12／昭和60改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造2階建、瓦葺、建築面積99㎡","structure_material":"石造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0205","desc":"敷地の南面西端に位置する桁行６間，梁間５間の石造２階建。外壁は大谷石で梁形，柱形をモルタル塗とする。小屋組はキングポストトラス。当初は東面中央に戸口を設け，２階に窓を開く。商品倉庫であった内部を改修し，越屋根と玄関を付加して歯科医院とした。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005926"},{"id":"00005925","register_sub_id":"101","register_pk":"106910","name":"島田商店旧事務所","kana":"しまだしょうてんきゅうじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40903149,"lng":139.33630028,"geo_status":"db","era":"明治後期／昭和12・60改造","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0204","desc":"店舗西に接続する木造平屋建で，桁行３間，梁間４間の東西棟。島田家が取得後，板敷の事務所とし，北側に変形６畳室があり，北辺の廊下が店舗に通じる。南面はパラペットを飾り，西妻の入口上はステップゲーブル形に整える。後に南側内部を車庫に改修した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005925"},{"id":"00005927","register_sub_id":"101","register_pk":"106912","name":"島田商店旧倉庫","kana":"しまだしょうてんきゅうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40923677,"lng":139.33626779,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0206","desc":"旧石蔵の背後，敷地北西隅に位置する。木造２階建，切妻造，桟瓦葺で，桁行６間，梁間５間。小屋組はキングポストトラス。東面中央の戸口に両開鉄扉を吊り，２階東面と南面に小窓を開く。外壁はモルタル塗で，鉢巻は洗出し仕上げとし，近代以降の特徴をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005927"},{"id":"00005824","register_sub_id":"101","register_pk":"106810","name":"島田商店店舗","kana":"しまだしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40900292,"lng":139.33638607,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0203","desc":"南と東で街路に面する木造２階建で，方３間半の入母屋造，桟瓦葺の東西棟。１階は庇下に折曲りの土間を設け，畳敷の店舗の北に８畳室を置く。２階は６畳座敷と次の間６畳と板間を配し，外縁に手摺を巡らす。街路側南東隅を切るなど，近代以降の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005824"},{"id":"00003808","register_sub_id":"101","register_pk":"104798","name":"正田醤油正田記念館","kana":"しょうだしょうゆしょうだきねんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24789804,"lng":139.52684096,"geo_status":"db","era":"嘉永6／昭和62移築","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積191㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0106","desc":"創業時の店舗主屋。主体部は桁行８間梁間３間半規模，南北棟，切妻造の木造２階建で，南面と東面に半間の下屋を設け，北面に桁行２間半梁間６間の平屋建を延ばすほか，西面は２階屋根を葺下ろして背面部を覆う。棟札から「大工棟梁栗原藤右衛門」が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003808"},{"id":"00002214","register_sub_id":"101","register_pk":"103204","name":"白井屋","kana":"しろいや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県吾妻郡中之条町大字中之条1798","lat":36.5870215,"lng":138.84343489,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、鉄板葺、建築面積111㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"10 － 0079","desc":"三国街道脇往還に通じる新道に東面して建つ。間口桁行７間，梁行４間規模，切妻造の木造２階建で，平入とし，２階を「せがい造」に造り，６畳の客室を５室配する。周辺に官公庁舎がたちはじめた明治２５年頃から宿屋を開業と伝える。明治期旅籠遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002214"},{"id":"00000187","register_sub_id":"101","register_pk":"101177","name":"積善館山荘","kana":"せきぜんかんさんそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県吾妻郡中之条町大字四万4236-1","lat":36.68633974,"lng":138.77348319,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建，鉄板葺，建築面積490㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"10 － 0008","desc":"四万温泉の老舗旅館の宿泊施設の一つで、前新とともに昭和初期の建築。本館の背後に建ち、木造２階建て、平面は突出した中央部を中心に左右対称の入母屋の屋根をつける変化に富んだ構成になる。施工の地元の職人の手になり、床廻りの意匠が特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000187"},{"id":"00003516","register_sub_id":"101","register_pk":"104506","name":"豊田屋旅館本館","kana":"とよたやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県高崎市八島町68","lat":36.322041,"lng":139.00914865,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"10 － 0100","desc":"高崎駅前通に北面して建つ。木造，２階建，入母屋造，桟瓦葺で，１階正面には庇を付け，中央玄関上部に唐破風を構える。客室５室を取る２階は，中廊下や周囲に廊下を配し各室の独立性を確保し旅館らしい平面とする。賑やかな外観の周囲でひときわ目立つ建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003516"},{"id":"00004933","register_sub_id":"101","register_pk":"105923","name":"中村弥市商店店舗","kana":"なかむらやいちしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-6-33","lat":36.41897355,"lng":139.34461445,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0136","desc":"本町通に接し，西面して建つ。桁行５間，梁間３間半，桟瓦葺，東西棟の木造２階建で，正面を寄棟造とする。東側以外の３方に半間の下屋を張出す。北側の路地に面する外壁は大壁とし鼠漆喰仕上とする。創建時の店構えを良く残し，織物産業の興隆を伝え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004933"},{"id":"00005762","register_sub_id":"101","register_pk":"106750","name":"平田家住宅旧店舗","kana":"ひらたけじゅうたくきゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-6-28","lat":36.4185732,"lng":139.34429093,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0199","desc":"本町通りに西面する間口３間半，土蔵造２階建の平入町家。切妻造，桟瓦葺で，表に瓦葺下屋を付ける。１階は土間に改修され，北側の店蔵の戸口前と東面に床板を張る。２階は床構えをもつ１０畳座敷がある。白漆喰塗の外壁に２階の重厚な塗戸内面の黒漆喰が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005762"},{"id":"00005783","register_sub_id":"101","register_pk":"106771","name":"平田家住宅旧店蔵","kana":"ひらたけじゅうたくきゅうみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-6-28","lat":36.4186017,"lng":139.3443109,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0200","desc":"本町通りに西面する間口３間半，土蔵造２階建の平入町家。切妻造，桟瓦葺で，表に瓦葺下屋を付ける。１階は土間に改修され，北側の店蔵の戸口前と東面に床板を張る。２階は床構えをもつ１０畳座敷がある。白漆喰塗の外壁に２階の重厚な塗戸内面の黒漆喰が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005783"},{"id":"00005583","register_sub_id":"101","register_pk":"106571","name":"法師温泉長寿館大浴場（法師乃湯）","kana":"ほうしおんせんちょうじゅかんだいよくじょう（ほうしのゆ）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県利根郡みなかみ町永井650他","lat":36.74428677,"lng":138.83019761,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0189","desc":"法師川東岸に，本館の北側に建つ。桁行１２ｍ，梁間１０ｍの規模で，木造平屋建，寄棟造，杉皮葺とする。屋根は和小屋に一部トラスを用い，棟上に櫓状の換気口を付ける。軒は四周をせがい造とし，外壁を下見板張とする。アーチ窓を開き，特徴ある意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005583"},{"id":"00005584","register_sub_id":"101","register_pk":"106572","name":"法師温泉長寿館別館","kana":"ほうしおんせんちょうじゅかんべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町永井650他","lat":36.74417659,"lng":138.8298859,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積276㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0190","desc":"法師川西岸に南北棟で建ち，桁行３７ｍ，梁間９ｍの規模で，木造２階建，切妻造，鉄板葺とする。１，２階共に客室を一列に並べ，川側に広縁をとって掃き出しのガラス戸を並べ，反対側は片廊下として，腰窓を付ける。外壁は漆喰塗で，落ち着いた意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005584"},{"id":"00005582","register_sub_id":"101","register_pk":"106570","name":"法師温泉長寿館本館","kana":"ほうしおんせんちょうじゅかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県利根郡みなかみ町永井650他","lat":36.74412659,"lng":138.83022379,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、杉皮葺、建築面積368㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0188","desc":"法師川東岸に南北棟で建ち，桁行３０ｍ，梁間１４ｍの規模で，木造２階建，切妻造，杉皮葺とし，軒をせがい造とする。１階に玄関，事務室等を置き，２階に客室をとる。玄関上部に切妻造の屋根を付け，２階正面には手摺を付ける。屋根には煙出しを上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005582"},{"id":"00002014","register_sub_id":"101","register_pk":"103004","name":"堀口家住宅付属屋","kana":"ほりぐちけじゅうたくふぞくや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県渋川市上ノ町2341","lat":36.495861,"lng":139.000214,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積131㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0056","desc":"街道に沿って店蔵の東面に接して建つ。木造２階建，東西棟の切妻造，もと板葺（現在は鉄板葺）で平入とする。１階は作業場を兼ねた店でトロッコレールを残し，２階は街道側を倉庫として使用していた。店蔵とともに明治の街道筋の面影を伝えており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002014"},{"id":"00002010","register_sub_id":"101","register_pk":"103000","name":"堀口家住宅店蔵","kana":"ほりぐちけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県渋川市上ノ町2335","lat":36.495884,"lng":139.000092,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0052","desc":"渋川における老舗の金物商家で，主要地方道渋川松井田線と平沢川とに挟まれた南北に長い敷地の北西隅に北面して建つ。間口４間奥行３間半規模の２階建，切妻造，桟瓦葺，平入の黒漆喰塗店蔵で，重厚さにおいて卓越している。年代は棟札による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002010"},{"id":"00004797","register_sub_id":"101","register_pk":"105787","name":"森合資会社事務所","kana":"もりごうしがいしゃじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-3-11","lat":36.4196099,"lng":139.34473883,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"10 － 0123","desc":"街路に東面する間口４間奥行６間の木造平屋建。正面北寄の玄関上部にペディメントを掲げ，銅板製の軒蛇腹を巡らし，外壁を白化粧煉瓦張とするなど洋風意匠を取り入れる。入口と窓の庇は反りをもち，垂木を見せた和風意匠とする。街路景観のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004797"},{"id":"00004798","register_sub_id":"101","register_pk":"105788","name":"森合資会社店蔵","kana":"もりごうしがいしゃみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-3-11","lat":36.41954876,"lng":139.34464524,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積82㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"10 － 0124","desc":"事務所の南に接続する桁行６間，梁間３間規模の土蔵造２階建である。切妻造，桟瓦葺で，街路に面した妻面の１，２階に窓を開き，漆喰塗の両開き戸を吊り込む。外壁は白漆喰塗で，２段の水切を塗出し，腰は石積とする。事務所と共に街路景観の一要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004798"},{"id":"00009129","register_sub_id":"101","register_pk":"164682","name":"山本館本店","kana":"やまもとかんほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県吾妻郡草津町大字草津字西町404","lat":36.62321014,"lng":138.59633507,"geo_status":"db","era":"昭和3年／昭和10年増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造地上3階地下1階建、鉄板葺、建築面積370㎡","structure_material":"木造地上3階地下1階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"草津温泉の湯畑の西隣に位置する。建築面積370平方メートル、木造3階地下1階建、入母屋造鉄板葺、塔屋付で、東面に千鳥破風を飾る。正面入口に構える唐破風造の玄関や、各階に廻らした軒庇が外観を特徴付けており、草津のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009129"},{"id":"00011061","register_sub_id":"101","register_pk":"205168","name":"横手館本館西棟","kana":"よこてかんほんかんにしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県渋川市伊香保町伊香保字香湯12-1","lat":36.49656,"lng":138.916439,"geo_status":"db","era":"大正10頃／昭和前期・同後期改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造4階建、鉄板葺、建築面積369㎡","structure_material":"木造4階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0330","desc":"東棟の西に続いて建つ。四階建で各階外壁をせがいで持ち出し、ガラス窓と化粧垂木付の水平庇を連続させる外観は東館と共通する。内部客室も当初の状況を良く残し、様々な銘木や趣向を凝らした造形、障子や欄間の精緻な細工も見事な上質の木造旅館建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011061"},{"id":"00011060","register_sub_id":"101","register_pk":"205167","name":"横手館本館東棟","kana":"よこてかんほんかんひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県渋川市伊香保町伊香保字香湯12-1","lat":36.496461,"lng":138.916701,"geo_status":"db","era":"大正9頃／昭和後期・平成22改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積519㎡","structure_material":"木造3階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0329","desc":"伊香保温泉の石段の上方東側に位置する旅館で、東館は敷地中央に建つ。木造三階建、入母屋造鉄板葺で、外周部はガラス窓と各階の庇を水平に連続させ、大屋根と庇には化粧垂木を付し、要所に庇を貫く化粧丸太附柱をアクセントとし、温泉街の景観に寄与する","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011060"},{"id":"00014136","register_sub_id":"101","register_pk":"508766","name":"青山茶舗旧納屋（楽風）","kana":"あおやまちゃほきゅうなや（らふ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市浦和区岸町四丁目84","lat":35.85513889,"lng":139.65509722,"geo_status":"db","era":"明治24年／平成4年改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"11-0214","desc":"中山道沿い商家の納屋で主屋背面側に南面して建つ。真壁造２階建、切妻造桟瓦葺平入で、正面に庇を架け、２階南面に２箇所窓を開ける。内部は各階東西二室に分け、一階背面側に一室配する。茶等の保管に使用した。街道沿いの広大な敷地中程に景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014136"},{"id":"00014135","register_sub_id":"101","register_pk":"508765","name":"青山茶舗店舗兼主屋","kana":"あおやまちゃほてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市浦和区岸町四丁目84","lat":35.855075,"lng":139.65483333,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"11-0213","desc":"浦和宿の南に位置。中山道に西面する店舗と棟を直交する主屋からなり、店舗は２階建切妻造桟瓦葺。正面に下屋を通し、軒、下屋とも出桁造とする。１階は南を土間、北を畳敷のミセとし２階も２室とる。主屋は平屋建で８畳２室。旧街道に重厚な店構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014135"},{"id":"00010920","register_sub_id":"101","register_pk":"208891","name":"秋田家住宅店舗兼主屋","kana":"あきたけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県所沢市寿町527","lat":35.791383,"lng":139.468085,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"11-0149","desc":"所沢駅北西の商業地で通りに南面し、一階前半部のミセの開口を広めて格子戸をたてる。切妻造の二階を東に寄せ、上下階とも出桁造で軒先まで銅板を張り防火を講ずる、特徴的な外観をもつ。二階には瀟洒な造作の座敷を設ける。織物業で栄えた当地の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010920"},{"id":"00000034","register_sub_id":"101","register_pk":"101024","name":"あさひ銀行川越支店（旧八十五銀行本店本館）","kana":"あさひぎんこうかわごえしてん（きゅうはちじゅうごぎんこうほんてんほんかん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川越市幸町４-２","lat":35.92258465,"lng":139.4831374,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階建塔屋・金庫室付、建築面積291㎡","structure_material":"鉄骨鉄筋コンクリート造3階建塔屋・金庫室付","registered":"1996.12.20(平成8.12.20)","register_no":"11 － 0001","desc":"ネオルネサンスリバイバル，サラセン風など各種様式を折衷的に用いた洋風銀行建築。設計は保岡勝也，施工は印藤順造。川越の伝統的な町並みの中で近代のあゆみを示す象徴として，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000034"},{"id":"00003380","register_sub_id":"101","register_pk":"104370","name":"朝日屋原薬局主屋","kana":"あさひやはらやっきょくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県志木市本町二丁目1618","lat":35.83379079,"lng":139.57950679,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"11 － 0049","desc":"街道に面して建つ店舗兼用住宅。木造２階建，切妻造，平入で西を正面とし，下屋庇を設ける。屋根はすべて桟瓦葺で，棟瓦を高く積む。１階は開放的な店構えだが，２階は窓に鉄格子をつけ，軒を出桁造とするなど，土蔵造と異なる重厚な外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003380"},{"id":"00000757","register_sub_id":"101","register_pk":"101747","name":"回漕問屋吉野屋土蔵","kana":"かいそうどんやよしのやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県ふじみ野市福岡3-4-12","lat":35.88562381,"lng":139.52303518,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造２階建，瓦葺，建築面積20㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"11 － 0006","desc":"吉野屋は安永２年(1773)に船問屋になり回漕業を営み栄えた家で，土蔵は新河岸川沿いにある旧屋敷地に建つ。二階建の小規模な土蔵だが，近辺では往時の建物が少なくなってきており，舟運で栄えた河岸の様子を物語る建物として貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000757"},{"id":"00004209","register_sub_id":"101","register_pk":"105199","name":"割烹旅館二葉本店本館","kana":"かっぽうりょかんふたばほんてんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県比企郡小川町大字大塚32-5","lat":36.05564652,"lng":139.26101152,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積461㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"11 － 0082","desc":"小川町駅からの駅前通りに西面して建つ。正面側は複雑な屋根構成をもち，内部２階には床の間と舞台を両面に配した７０畳の大広間を設ける。東京から棟梁を招いて造らせたと伝える。吟味された用材とともに職人芸が随所に発揮された数寄屋風料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004209"},{"id":"00004210","register_sub_id":"101","register_pk":"105200","name":"割烹旅館二葉本店六六亭","kana":"かっぽうりょかんふたばほんてんろくろくてい","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県比企郡小川町大字大塚32-5","lat":36.0557028,"lng":139.26129272,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"11 － 0083","desc":"本館の東方，庭園内の池畔に建つ。逆Ｚ字形の棟をもつ寄棟造，桟瓦葺の平屋建で，内部は４畳半と８畳の客室２室等から成り，池上の８畳茶室は船底天井をもち，南面と東面に高欄付きの縁を廻す。本館と同様銘木奇木を用いた数寄屋風離れの好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004210"},{"id":"00009905","register_sub_id":"101","register_pk":"196052","name":"金子家住宅主屋","kana":"かねこけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県入間郡越生町大字越生字町769","lat":35.96394214,"lng":139.29757897,"geo_status":"db","era":"安政5／明治前期・大正期改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造2階建、瓦葺、建築面積230㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"11 － 0141","desc":"通りに南面して建つ。出桁造の二階建で、一階前寄りをミセとして正面に下屋を設ける。ミセ・チャノマの西側に座敷を張出し、背面側に通土間を通じて広い土間を設ける。二階にも四室の座敷を設ける。生糸産業で栄えた当地における幕末の商家の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009905"}];
